quests[26721] = { id = 26721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Jitters-Bugs", description = "M-Master Harris requires many reagents for his serums. He has me gather them for him.\n\nMost of it's not so bad... I mean, the corpseweed is pretty bad, but it's not as bad as the widow venom. Have you seen the widows around here? The hatchlings are the size of a man. Even with a gun, I can't stand to go out hunting them!\n\nIt's just too terrifying. If you'll go do it for me, I'll gladly pay you! Just bring me back some widow venom! You'll find them all in the woods to the east, just north of the road.", progress = "Did you get it? Please tell me you got it...", completion = "Oh thank you, thank you! You've saved me from having to go out in the woods with those awful things!\n\nAt least for a day, that is...", objectives = "Collect 8 Widow Venom Sacs from Black Widows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26722] = { id = 26722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buried Below", description = "<You attach the arch to the rod, and the artifact is nearly complete. A large gap still sits at the center of the holy symbol's head.>\n\n<Once again you feel it tug your arm, urging you towards the hole in the wall and the winding tunnel ahead. The last piece must be through there.>", completion = "<In the darkest depths of this earthen tunnel, you spy the faintest gleam. The last piece is found!>", objectives = "Search the tunnel under the Dawning Woods Catacombs for the Lightforged Crest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26723] = { id = 26723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Morbent Fel", description = "Before I was lost to the woods, the last thing I remember is Morbent Fel. He was a vile necromancer, and the reason this land swarms with so many vile undead.\n\nI asked an adventurer to help me put an end to him. I thought they did! But Sister Elsington tells me the land still crawls with ghouls and spectres ripped from the grave.\n\nMorbent Fel should have breathed his last in the house on Forlorn Rowe, north of Raven Hill Cemetery. Go there and see what's become of him...", progress = "What did you find?", completion = "His clothes and bloodstains? If it's not tricks, it's something worse...", objectives = "Search Forlorn Rowe for signs of Morbent Fel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26724] = { id = 26724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lurking Lich", description = "The others here share my suspicion. Morbent Fel lives on in undeath...and may be even more powerful than before. A necromancer was struck down, but a lich may have risen in his place. And now he continues to ruin this land.\n\nI remember Duskwood before all this, {name}. I remember bright skies and peaceful woods. This can't stand! Morbent Fel must be stopped for good.\n\nSpeak to Sister Elsington. Her vision might guide you to where Morbent Fel is, and how he can be defeated.", completion = "It's heartening to see one so recently recovered be so concerned with the plight of others. Sven spares himself suffering by not dwelling on his own misfortune.", objectives = "Speak with Sister Elsington.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26725] = { id = 26725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guided by the Light", description = "Sven is correct. I can feel the presence of a powerful evil deep beneath the Raven Hill Cemetery. Evil lurks in its catacombs, and Morbent Fel must be the source.\n\nYou will need the power of the Light to strike him down, {name}. Sven told me the heroes who first slew Morbent Fel wielded an artifact of lightforged iron, imbued with holy power. That artifact is still here!\n\nI can feel it as well, a glimmer of light amidst the darkness. Search Raven Hill for it, and let the Light guide you through it.", completion = "<Buried in the cold dirt, you find a brilliant metal shaft. But there are holes where pieces of the artifact are clearly missing.>", objectives = "Find the Lightforged Rod in Raven Hill Cemetery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26726] = { id = 26726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Triumphant Return", description = "Return to Lakeshire and let Solomon know that the Blackrock invasion has been stopped. Make sure he understands the cost at which our freedom came - that we lost five of our finest heroes to save Redridge and ultimately, Stormwind.\n\nYou are the last surviving member of Bravo Company, {name}. It is up to you to keep its legacy alive.\n\nDismissed.", completion = "They will never be forgotten, {name}. What you and the rest of Bravo Company sacrificed in order to save Redridge will be a tale told for ages to come.\n\nWhile I can in no way make up for the loss of your friends, I feel that you must be rewarded for such a heroic deed. These are Keeshan's possessions - the only things we found when we dredged the lake for his body. Troteman has informed me that Keeshan would have wanted you to take something as the lone surviving member of Bravo Company. Remember them, {name}!", objectives = "Report to Magistrate Solomon at Lakeshire in Redridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26727] = { id = 26727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Embalmer's Revenge", description = "You're not the first fool to be manipulated by Abercrombie! That doddering old man is known as The Embalmer to us. He's a vile necromancer and a blight upon this town.\n\nAnd now, sewn together and given life by the very materials you brought him, his horrible creation approaches!\n\nThat hideous creature will be upon us in mere moments! If you have any heart, {name}, you'll help the Night Watch drive off the abomination and save our town!", progress = "Don't just stand there! He's right outside! By the light, man, do something!", completion = "Thank the Light, he's gone...\n\nI'll say you've made amends by helping save the lives of those here, {name}.", objectives = "Slay Stitches in Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26728] = { id = 26728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Duskwood!", description = "{name}, the citizens of Duskwood are in dire need of your assistance! I have here a letter from Commander Althea Ebonlocke, leader of the Night Watch, pleading for help.\n\nTo reach Darkshire you should travel across the bridge located in the southwest corner of Redridge. Once you cross the bridge you will be in Duskwood. Then you just follow the road to Darkshire. Beware of the savage beasts that stalk the countryside!", completion = "You are the help that we requested?\n\n<Althea sighs.>\n\nI suppose you will have to do.", objectives = "Report to Commander Althea Ebonlocke at Darkshire in Duskwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26729] = { id = 26729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Water Elementals", description = "I arrived in Stranglethorn to study a feature known as the Altar of Naias, but made the unfortunate choice of denying Colonel Kurzen's advances, which earned me several years in that cage.  Now that I'm out, I figure I might as well continue with my original studies.\n\nThe altar is on an island to the west, south of Zul'Kunda.  Gather some of the bracers from the island's water elementals.\n\nOh, and you can use this device when you're finished.  No need to make you walk all the way back here.", progress = "Yes, {name}?", completion = "These will do for my purposes.  Though we can't activate the altar with bracers alone...", objectives = "Acquire 6 Water Elemental Bracers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26730] = { id = 26730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Can Take the Murloc Out of the Ocean...", description = "I need something to cut into the raw, elemental power of these bracers... something strong and abrasive, but still of the sea.\n\nThe Murkgill murlocs have moved inland from the sea, but they still carry vials of sea salt on them.  What they use it for, I can't be sure, but it will serve for our studies.  You can find the Murkgill in the glade south of the Rebel Camp and east of Bal'lal ruins.", progress = "The salt?", completion = "We have what we need.  Are you ready to activate the Altar of Naias, {name}?", objectives = "Obtain 6 vials of Sea Salt from Murkgill murlocs in Northern Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26731] = { id = 26731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Altar of Naias", description = "The salt you brought was sufficient to activate the bracers' innate enchantments.  I have taken these enchantments and combined them into a summoning token... a gift, if you will.\n\nReturn to the Isle of Naias, and place the gift on Naias' altar.  Call me again once you have Naias' heart.", progress = "I eagerly await the results.", completion = "My colleagues within the Kirin Tor will be happy to learn that the heart is ours.\n\nThank you for your assistance, {name}.  I couldn't have done it without you.", objectives = "Use the Gift of Naias to summon Naias, then obtain the Heart of Naias.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26732] = { id = 26732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bad Medicine", description = "I have a feeling that Kurzen's Medicine Men are distributing more than just medicine.  Kurzen needs some way to quelch insubordination, and an elixir under the guise of \"medicine\" would be the perfect way to do that.\n\nWe need those remedies for research.  Search the Kurzen Compound to the southeast - his medicine men and jungle fighters should carry the remedies on their bodies.", progress = "I'm a little bit of an alchemist in my spare time, you know.", completion = "Well done, {name}.  Now, let's see what they've got in this elixir of theirs...", objectives = "Obtain 7 Jungle Remedies from the Kurzen Compound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26733] = { id = 26733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Control Sample", description = "<Brother Nimetz analyzes the samples you've given him.>\n\nThis... this is just basilisk blood!\n\nNo, it's mostly basilisk blood.  They've added something to it though.  I'll need a control sample to perform a proper comparison.\n\nThey most likely obtained the blood from the crystal spine basilisks, found to the east of their compound.  Bring me back some pure samples, and I'll have this elixir figured out.", progress = "There's something not quite healthy about this elixir, {name}.  Even though I haven't completed my analysis, I can sense it.", completion = "This will do.  Please hold on for a moment while I test this out.", objectives = "Obtain 7 samples of Crystal Spine Basilisk Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26734] = { id = 26734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Source of the Madness", description = "After reducing the basilisk blood out of the elixir, I've uncovered an unusual precipitate.  It appears to be a blue crystal of some sort...\n\n<Brother Nimetz consults his notes.>\n\nIt's not a singing blue crystal... not a pulsing blue shard...\n\n<He flips forward a few pages.>\n\n... not a piece of the Mind's Eye.  Nope, this isn't something we've seen before in Stranglethorn.  If anyone has any more of this substance, I want it.  Check the high-ranking Kurzen troops, in the back of their cave.", progress = "Make sure you handle that stuff carefully, {name}.  We don't know what it is.", completion = "<Brother Nimetz opens up a pouch and lets you place the crystal inside.>\n\nI knew they'd have some more of this substance.  I'm going to send this to my contacts at Fort Livingston, to the south.  Hopefully they'll have some more luck with it.\n\nThank you for everything, {name}.", objectives = "Obtain a Whispering Blue Stone from Kurzen troops within the Stockpile.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26735] = { id = 26735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Kurzen", description = "Hello, {class}.\n\nWe are soldiers of Stormwind, and rebels from Kurzen's Compound, a large outpost that you'll find just to the southeast of here.  We were under the command of Colonel Kurzen, until he and those close to him started to descend into madness...\n\nWe rebelled, set up camp here, and stood against Kurzen.  Now, my sources are telling me Kurzen has disappeared.  I trust my source, but it would help to hear from a third party.  Please, head into the compound and find some documentation of his fate.", progress = "What were you able to find, {name}?", completion = "They KILLED him?  And all this time, I thought he had them underneath an iron bootheel...", objectives = "Obtain the Kurzen Compound Prison Records and the Kurzen Compound Officers' Dossier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26736] = { id = 26736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spared from Madness", description = "Kurzen's death is a relief, but what's more interesting, and perhaps more immediate, is the sign of some potential allies within the compound.\n\nI don't care what it says on that prison record, I know EXACTLY why those 3 were locked up: refusal to follow orders.  They must have been spared from the madness, much like my fellow rebels here, and incarcerated for speaking up.\n\nFind them, {name}.  Find them, and send them back here.", completion = "Thank you, {name}.  It looks like my suspicions were correct... the three prisoners seem to have escaped the affliction that gripped Kurzen and the rest of his men.\n\nBefore you arrived, Emerine teleported them over to Stormwind to get cleaned up after their ordeal.  They promised to return soon.", objectives = "Rescue Berrin Burnquill, Emerine Junis, and Osborn Obnoticus inside Kurzen's Compound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26737] = { id = 26737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stopping Kurzen's Legacy", description = "Now that our allies have been evacuated, it's time to run a final raid on Kurzen's Compound.  They will never be weaker than they are right now, and with your help, we may be able to weaken them beyond repair.\n\nThose four names that were listed in the Officers' Dossier - Anders, Gaulus, Miranda, and Esquivel - will be the highest-ranking personnel remaining.  Look for them in that cave in the back of their compound.  Removing all four will be devastating to Kurzen's forces.\n\nGo with honor, {name}.", progress = "Remove the heads, {name}.  I know you can do it.  My men will clean up the remainder of their forces after you are done.", completion = "Marvelously executed, {name}.  My men and I can handle the rest.\n\nWith Kurzen out of the picture, we may be able to continue our original expedition here in Stranglethorn, which was... ahh...\n\nNo matter.  Please, feel free to peruse our armor stores.  You may find something that fits you well.", objectives = "Kill Chief Anders, Chief Gaulus, Chief Miranda, and Chief Esquivel within The Stockpile.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26738] = { id = 26738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Hatched", description = "While looking through this soldier's possessions, you look down to see a newborn raptor hatchling looking back up at you.  Was it following this Kurzen militiaman the whole time?\n\nYou can see it studying you, learning your features and following your movements.\n\nThe lashtail hatchling has formed a bond with you.\n\nPerhaps someone back at the Rebel Camp will know what to do with a raptor hatchling.", completion = "Yes, the little one seems to have taken a liking to you.  You're lucky... at this age, the raptors are calm, peaceful, and easily trained.  Keep her, {name}... she may come in handy.\n\nIn fact...", objectives = "Bring the Lashtail Hatchling to Corporal Sethman at the Rebel Camp in Northern Stranglethorn.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26739] = { id = 26739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Think She's Hungry", description = "It looks like your young raptor is hungry.  If you're looking to keep her, why don't you find something for her to eat?  The lashtail often attack the basilisks of Stranglethorn, which can be found to the east, beyond Kurzen's Compound.\n\nShe probably isn't strong enough to hunt on her own yet, but I'm sure she will eat freshly killed basilisk meat.", completion = "She looks bigger already!  You can see, these raptors grow quickly.  You are lucky to have found such a strong companion.\n\nKeep her by your side as long as you can, {name}.  I'm sure she will prove to be an asset in the future.", objectives = "Kill Crystal Spine Basilisks in Northern Stranglethorn, and let your Lashtail Raptor eat 40 bites of their meat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26740] = { id = 26740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krazek's Cookery", description = "I do most of the cooking at the camp.  It used to be a lot of work, until I bought a mechanical cooking pot from a goblin merchant.  The pot is a wonder!  It saved me countless hours...until it broke!\n\nCan you take the pot back to the goblin for me so he can fix it?  His name is Krazek.  Last I heard, he was staying with Nesingwary in the hunters' camp just to the south.", progress = "Hello!  You brought me something?", completion = "Oh I see, it's a Krazek's Crock Pot!  An ingenious piece of work, but it can break a spring or throw a gear now and then.  Let me see what's wrong with this one...\n\nAha!  Its steam charger is rusted out, it has a cracked knuckle-gasket and its fobulator is missing teeth.  I'm surprised the pot could even boil a turnip in this state!\n\nCan I fix it?  Of course I can fix it!\n\nBut there's a price.  Oh yes, there is always a price...", objectives = "Bring Krazek's Crock Pot to Krazek.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26741] = { id = 26741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[26742] = { id = 26742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodscalp Insight", description = "I never got to properly thank you for saving me.\n\nThank you, {name}.\n\nI'm still a little fatigued from my captivity, so I thought you might help me with my studies.  As a shaman of the Wildhammer clan, I'm very interested in the shamanic practices of the Bloodscalp tribe.\n\nTheir magic seems to have diverged in an interesting direction.  If I had one of the totems that their shaman use, I could begin my studies.  You'll find them at the Bal'lal ruins, on the coast to the southwest.", progress = "Beware: they may put up a fight.", completion = "<Berrin studies the inscriptions on the totem.>\n\nI think I can read this text... Fascinating!\n\nTsul'kalu, Mahamba, Pogeyan... what are these names?", objectives = "Obtain a Bloodscalp Totem from a Bloodscalp Shaman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26743] = { id = 26743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sacred to the Bloodscalp", description = "Ahh... these must be names of their totemic creatures - the animals that they attribute to the spirits.  Let's see... Mahamba as water, Tsul'Kalu as earth, Pogeyan as... air?  Fire?  I can't make this part out.\n\nI'd like some more information on these spirits of theirs.  The Bloodscalp have a camp close to here, in the Tkashi ruins.  Maybe you can find some details there.", progress = "It's likely that these totemic creatures are based on some of the fantastic creatures that roam this jungle.", completion = "First you save me from the madman's jail cell, and now you bring me some keys to understanding trollish shamanism.\n\nThis is turning out to be a pretty good week!\n\nThank you again, {name}.  I will see to it that you have the support of the Wildhammer clan as you continue on your journeys.", objectives = "Obtain an Icon of Tsul'kalu, an Icon of Mahamba, and an Icon of Pogeyan from Bloodscalp trolls in the Tkashi Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26744] = { id = 26744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep Roots", description = "On a somewhat unrelated note, I've been putting together a collection of troll stories and legends for a... personal project.  I was just thinking you might be able to help me find some of them.\n\nThe Bloodscalps at the Bal'lal ruins, on the coast to the southwest, maintain a large tablet documenting some of their stories.  Of course, I'll reimburse you if you're able to bring any of these stories back to me.", progress = "Did you make it down to Bal'lal Ruins yet?  Did you find the tablet?", completion = "To be honest, I'm sending this information home to Stormwind, for my wife and son.  They love to hear about what I've been doing out here in the jungle, and I only get to visit so often.  Every little bit helps.\n\nThank you, {name}.", objectives = "Obtain the Bloodscalp Lore Tablet from the Bal'lal Ruins in Northern Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26745] = { id = 26745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favored Skull", description = "Your pet raptor seems to have found a new toy: a skull, from a nearby troll skull pile.\n\nWhat sets this skull apart from the rest is beyond you, but for some reason, she won't put it down.\n\nOsborn Obnoticus, the gnome you saved from Kurzen's Compound, is an expert in troll history and physiology.  Maybe he'll have some idea what makes this one so special.", completion = "What do we have here?  A young raptor, and her pet {race}.  Hah!\n\nMore importantly, what is that skull you have there?  This was no ordinary troll.  He was big...\n\n\n\n... and strong, too.  You know, I've been meaning to try my hand at some troll magic.  How hard could it be?  Let's use this strong fellow as a test subject, shall we?", objectives = "Report to Osborn Obnoticus at the Rebel Camp and show him your Lashtail Hatchling's new skull.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26746] = { id = 26746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Nose for This Sort of Thing", description = "<Osborn looks at the skull again.>\n\nIn life, he was strong, powerful, a lord among trolls.  With our help, he can be a lord once more.\n\nThe Bloodscalp scavengers that wander the ruins to the southwest hoard magical fetishes that can help us.  They hide these artifacts under the ground.  Use your hatchling to find these artifacts, {name}... then bring them here.", progress = "How many did you find?", completion = "These will provide a bit of... what's the troll word?  Voodoo?  Juju?  Tiklabang?\n\nIt doesn't matter.  If we're going to re-build a troll, we need troll magic, and these fetishes are full of it.", objectives = "Use your Lashtail Hatchling to sniff out 8 Tkashi Fetishes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26747] = { id = 26747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Physical Specimen", description = "The soul is ready, but the body is not.  For a skull as well-formed, as marvelous, as beautiful as this... we will need a suitable body.\n\nThe chief of the Bloodscalps, Gan'zulah, won his throne with brute force.  If he still lives, you'll find him in Zul'Kunda, to the west.\n\nTaking his body won't be easy, but nothing a sturdy {class} like yourself couldn't handle.  Bring it back here when you're done.", progress = "Gan'zulah was a brute and a tyrant.  I've got a feeling that this troll will be different.  This troll magic is easier than I thought it would be!", completion = "You have done well, {race}.  We have a head, a body, and some juju-voodoo-mojo nonsense.  Now, just a little shock of electricity to get things started, and...", objectives = "Obtain Gan'zulah's Body from Zul'Kunda.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26748] = { id = 26748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodlord Mandokir", description = "{race}.  You just resurrected your worst nightmare.  You didn't think I was a friend, did you, {race}?  Ah, ha ha haaaa!\n\nYou've served your purpose.  I've returned to the realm of the living, and it's all thanks to you.  So, instead of killing you, I'm going to make you a deal instead.\n\nGive me that raptor.\n\nYou must already know that she's no normal raptor, and I need a replacement for Ohgan.  Do it, or both you and the gnome will taste my rage.", progress = "All I ask is the raptor, {race}.  Give it to me, and the gnome lives.", completion = "I'm glad to see you've come to your senses.\n\nCome and visit us in Zul'Gurub sometime, {race}.  I'll be watching...", objectives = "Deliver the Lashtail Raptor Egg Fragment to Bloodlord Mandokir in the Rebel Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26749] = { id = 26749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priestess Thaalia", description = "Thank you, {name}.  I know you didn't have to save my life.\n\nThe return of Bloodlord Mandokir is ill news.  He was killed inside Zul'Gurub several years ago, and we thought we had seen the last of him and his kind.  The trolls of Zul'Gurub were attempting to perform a hideous, horrible ritual.  If Mandokir is alive, then it stands to reason that he is not the only one.\n\nThe explorers at Fort Livingston, far to the south, may know more.  Speak with their priestess.", completion = "Mandokir is alive, yes.\n\nYou are responsible, yes.\n\nYou may be able to stop him still, yes.", objectives = "Speak with Priestess Thaalia at Fort Livingston in Northern Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26750] = { id = 26750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At the Stonemother's Call", description = "It is time. The Stonemother will speak with you. You can find her throne in northern Deepholm, above the Scoured Reach.", completion = "So you've come.\n\nFleshlings just like you killed my daughter... my only daughter. With no provocation.\n\nNot sated at stripping me of my family, more of you flocked to Deathwing to serve him in ravaging my home.\n\nYou're quite arrogant to come before me asking for MY help. I'm tempted to crush you where you stand.", objectives = "Speak to Therazane, the Stonemother.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26751] = { id = 26751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Population Con-Troll", description = "I understand you may be headed to Zul'Kunda soon.  While you are there, I have a small task for you.\n\nThe trolls are outgrowing Stranglethorn.  The Bloodscalp in the West, the Skullsplitters in the East... they pour out of their ruins and into the jungle, disrupting the natural balance of the region.  It is time we restored that balance.\n\nZul'Kunda is the Bloodscalp capital.  Inside you will find the most high-ranking Bloodscalps.  Reduce their numbers, then return to me.", completion = "Balance is restored - for now.  We may call on you again in the future, {name}.", objectives = "Slay 7 Bloodscalp Mystics, 7 Bloodscalp Hunters, 7 Bloodscalp Scouts, and 1 Bloodscalp Beastmaster.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26752] = { id = 26752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audience with the Stonemother", description = "Stay where you are, champion. I have not yet decided what to do with you or your Earthen Ring.", completion = "Ya've done well, brotha. Da Stonemother be listenin' and da World Pillar is not far from our reach.", objectives = "Attend the Audience with the Stonemother.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26753] = { id = 26753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Halls of the Dead", description = "<In front of you, the bare earth slopes down towards the dark entrance to the crypts.>\n\n<You can feel the tug of the lightforged artifact urging you towards it. Perhaps the other piece is down there?>", completion = "<In the dirt of this alcove, your eye catches the shine of brilliant metal. You've found another piece of the artifact!>", objectives = "Find the Lightforged Arch within the Dawning Woods Catacombs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26754] = { id = 26754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morbent's Bane", description = "<The pieces fit, and the holy artifact is restored, gleaming with sacred light. This should let you defeat Morbent Fel's dark magic.>\n\n<Further down the tunnel, away from the direction you came from, a heinous cackle rings out. It's the clattering laugh of a lich. Morbent Fel is just ahead!>", completion = "May the disgusting monster stay dead this time!\n\nI'll head down there and scatter his remains to ash myself, {name}. You've done a great thing; perhaps in time Duskwood can return to its former peaceful state.", objectives = "Use Morbent's Bane to weaken Morbent Fel and defeat him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26755] = { id = 26755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep Them off the Front", description = "Oh good, you brought another catapult with you! Clay might be older than dirt, but he makes a mean war machine.\n\nWell, you didn't bring it all the way out here for your health, flesh bag. Get in one of those things and bombard the fungal terrors and reinforcements streaming out of Needlerock Slag.\n\nWe have to keep them off the front!", progress = "Get back in a catapult and put those things back in the ground. The line's barely holding!", completion = "That's a great start, {name}, but we're going to need you to fly over into the town and stir up some trouble.", objectives = "Bombard 30 Fungal Terrors and/or Stone Trogg Reinforcements.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26756] = { id = 26756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nessa Shadowsong", description = "A friend of mine, Nessa Shadowsong, is a fishing merchant in Rut'theran Village.  She needs a parcel taken to Darkshore, and is looking for someone to help her.\n\nIf you're interested, then to reach Nessa you must take the portal in Darnassus to Rut'theran Village.  You will find the portal west of the Temple Gardens.", sourceObjective = "Speak with Nessa Shadowsong.A friend of mine, Nessa Shadowsong, is a fishing merchant in Rut'theran Village. She needs a parcel taken to Darkshore, and is looking for someone to help her.\n\nIf you're interested, then to reach Nessa you must take the portal in Darnassus to Rut'theran Village. You will find the portal west of the Temple Gardens.", sourceObjectiveStatus = "unverified-source-field" }
quests[26757] = { id = 26757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bounty of Teldrassil", description = "The fishermen of Rut'theran village do very well, for the fish here are extremely large and abundant.  I would like to compare the bounty here with that of the mainland.\n\nI have a collection of fish bones and scales that I would like taken to a colleague of mine in Darkshore.  His name is Laird, he is a fish vendor in the village of Auberdine.\n\nBring my collection to our hippogryph master, Vesprystus, and speak to him about traveling to Auberdine.", objectives = "Bring Nessa's Collection to Vesprystus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26758] = { id = 26758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight to Auberdine", description = "From Rut'theran, there are two methods of travel to Auberdine: by ferry and by hippogryph.  Both are quick and reliable, but if you have not yet flown to Auberdine by hippogryph, then I suggest you do.\n\nIt is sound advice to speak with the hippogryph master in every town that has one.  Once you speak to the master, you can then fly there from other towns.\n\nHere is Nessa's collection.  Speak with me again when you are ready to fly to Auberdine and deliver Nessa's collection to Laird.", objectives = "Ride a hippogryph to Auberdine from the hippogryph master Vesprystus, then bring Nessa's Collection to Laird.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26759] = { id = 26759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Nessa", description = "I must send a response to Nessa.  She'll be very interested to know how different the fish here are from those along Teldrassil's coastline.  We can only guess the cause, but it is my suspicion that the world tree itself is affecting the wildlife around it!\n\nPlease, take this response to Nessa.  If you wish to take a hippogryph back to Rut'theran then speak with the hippogryph master Caylais Moonfeather.  If you wish to take the ferry, then one regularly departs from the dock to the northwest.", objectives = "Bring Laird's Response to Nessa Shadowsong.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26760] = { id = 26760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cry For The Moon", description = "I'm hopeful, but let's remain professional. It's business as usual for this one.\n\nInto the guillotine he goes... and if the alchemy doesn't take, he won't be getting back out of it.\n\nJitters and I will attend to this. Please, just stand back and watch from a safe distance.", completion = "Success... Finally! I can't thank you enough for giving me the chance to work the cure myself.\n\nOur new friend may be in need of some help as well. You might want to speak with him.", objectives = "Watch Oliver Harris and Jitters attempt to cure the Lurking Worgen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26761] = { id = 26761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Threat to the Kingdom", description = "There is no doubt that the Defias pose a great threat to the kingdom, but we certainly cannot enter their hideout and hope that everything will work itself out. No, an assault against the Defias is going to take time and planning. I want you to leave the logistics to me. Our kingdom has other threats that must be dealt with immediately!\n\nTravel east through Elwynn to Redridge and report to Magistrate Solomon in Lakeshire. I will call for you when we are ready to attack the Defias.", completion = "I heard about the Defias making a return. Terrible news. I wish I had better news, but it would appear that Lakeshire is under attack! We are losing citizens left and right. Our own guards are spread far too thin to handle the situation. We need a hero to step up!", objectives = "Report to Magistrate Solomon at Lakeshire in Redridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26762] = { id = 26762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reactivate the Constructs", description = "We sent a number of our war constructs north into Needlerock Slag, but none of them ever returned. We know that the stone trogg mystics have done something to them.\n\nWhat we're concerned about is that the mystics will control and turn them against us, like they have with the fungal giants.\n\n{name}, go into the stone trogg town and reactivate the constructs.", completion = "That was a nice bit of work, {name}.\n\nWith our constructs back up and running behind their main lines, it's only a matter of time now before we make the big push through and rescue the Stonefather.", objectives = "Reactivate 5 Deactivated War Constructs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26763] = { id = 26763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venture Company Mining", description = "If I'm going to repair this pot, I'm going to need reagents.  And to get them, you're going to have to do an eensy little bit of killing.  I hope you don't mind.\n\nThose dastardly Venture Company geologists have been collecting some tumbled crystals that will suffice for what I need.  You'll find them around their Base Camp, on the other side of Lake Nazferiti, to the east.\n\nI don't care what you have to do to get them.", progress = "Do you have those crystals?", completion = "These will work fine.  Just a moment please.\n\n<Krazek thrusts the stones into the cooking pot and wiggles them around a bit.>\n\nAll fixed!", objectives = "Obtain 5 Tumbled Crystals from Venture Co. forces near Lake Nazferiti.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26764] = { id = 26764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Low", description = "You may notice that the Venture Company has completely clear-cut all the trees around their Base Camp to the east.  Not one to miss out an opportunity for profit, their foreman has enslaved druids, and is forcing them to re-grow the forest so they can chop it down again!\n\nPersonally, I find this abhorrent, and not just because I didn't think of it first.\n\nRelease a few of these druids from their captors.  I'm sure they'll appreciate it.", sourceObjective = "Free 3 Enslaved Druids from the Venture Co. Base Camp.You may notice that the Venture Company has completely clear-cut all the trees around their Base Camp to the east. Not one to miss out an opportunity for profit, their foreman has enslaved druids, and is forcing them to re-grow the forest so they can chop it down again!\n\nPersonally, I find this abhorrent, and not just because I didn't think of it first.\n\nRelease a few of these druids from their captors. I'm sure they'll appreciate it.", sourceObjectiveStatus = "unverified-source-field" }
quests[26765] = { id = 26765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Corporal Kaleb", description = "So, this pot is fixed.  I even added an extra steam whistle, and look!  There's a new chopper at the bottom that'll cut through leg bones!\n\nYes yes, Krazek's Crock Pot is a 100% cook pleaser!  I'm sure its owner will be satisfied.", progress = "Hello, {name}.  Did the goblin Krazek fix my pot??", completion = "It's fixed!  This is great, now I can get dinner started!  Thanks so much, {name}.\n\nI hope Krazek didn't give you too much trouble.", objectives = "Bring Krazek's Fixed Pot to Corporal Kaleb at the Rebel Camp in Northern Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26766] = { id = 26766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Big Game, Big Bait", description = "We're only going to get one shot at capturing Abyssion, {name}.  Let's make it count.\n\nWe'll test out the trap on the biggest of the stone dragons in the Alabaster Shelf.\n\nTo lure the stone matriarch, we're going to need to gather sufficient bait.\n\nTake this knife and carve 5 sides of basilisk meat.  That ought to be enough even for her appetite.", progress = "Did you obtain the meat?", completion = "That should be enough to lure the beast, {name}.", objectives = "Use Mylra's Knife to obtain 5 Sides of Basilisk Meat from dead Jadecrest Basilisks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26767] = { id = 26767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Figuring out how to make quests", description = "Whee!  You get to make a breadcrumb quest!  Now figure out what to do next.", sourceObjective = "Make a breadcrumb quest.", sourceObjectiveStatus = "unverified-source-field" }
quests[26768] = { id = 26768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Catch a Dragon", description = "Having a dragon guard the fragment was a smart move on the enemy's part.  They can keep moving its location any time we get close to it.\n\nCatching Abyssion will be extremely difficult, but I have a plan that might help.\n\nThe Twilight's Hammer uses magical traps to bind stone drakes to the ground while they drain their energy.\n\nIf we can get our hands on one of these, we might be able to ground the Twilight Dragon for just long enough.\n\nGo east of here, to the Alabaster Shelf, and obtain a trap.", progress = "If the snares are good enough for stone drakes, they might work on Abyssion.", completion = "Let's see if the snare can ground something larger than a drake.", objectives = "Obtain a Dragon Snare from the Twilight Dragonstalkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26769] = { id = 26769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raging River Ride", description = "Enjoy your cut of the loot, {name}!\n\nI hate to share, but business is business. And that double-dealer Nozzlepot is guaranteed a 10% cut of this treasure. Can you deliver this to him at his outpost in the north?\n\nHe's got a little research station upstream, along the river. If you travel just northeast of town here, Horton Hornblower can give you a free ride on one of his riverboats. Tell him I sent ya!", progress = "Welcome, {class}. Fresh off the boat from Ratchet? Any news?", completion = "<Nozzlepot snatches the bag of gems from you.>\n\nGazlowe calls this 10%? You tell him I'm going to weigh these!\n\nI suppose he expects me to pay you a delivery fee, as well? Fine, fine. Have some spoils!", objectives = "Board Horton Hornblower's Riverboat northeast of Ratchet and get a riverboat ride to Nozzlepot's Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26770] = { id = 26770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystic Masters", description = "The Needlerock mystics have taken control of the fungal giants that have sprouted in their chasm, down below. Now they seek to control our war constructs.\n\nGo north into Needlerock Slag and do something about it! Isn't that what you're here for?", completion = "A few less stone troggs is always a good thing. Glad to see that you're a decent {class} after all.\n\nWe'll soon know the exact location where they're keeping my father captive. Hope you survive until then.", objectives = "Slay 5 Needlerock Mystics.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26771] = { id = 26771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testing the Trap", description = "You must set the trap for the matriarch now.\n\nGo to the western end of the Alabaster Shelf and place the trapped basilisk meat in the center of the feeding grounds.", completion = "Well done, {name}.  Here's to hoping the trap performs as well when we try it on Abyssion.", objectives = "Place the trapped meat in the western end of the Alabaster Shelf.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26772] = { id = 26772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mind Vision", description = "To know Mandokir, you must see Mandokir.\n\nTo see Mandokir, you must use eyes of raptor.\n\nYou have formed bond with raptor: Ohgan'aka: daughter of Ohgan.\n\nTo strengthen bond, we need feathers.\n\nYou will go northeast, and you will find the feathers, yes.", progress = "Raptor named Ohgan'aka, still your friend.", completion = "You bring feathers, yes.\n\nYou can follow directions, yes.", objectives = "Obtain 5 Jungle Stalker Feathers from Jungle Stalkers in Northern Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26773] = { id = 26773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "See Raptor", description = "We have the feathers, yes.\n\nWe have the {class}, yes.\n\nSpeak with Priestess when you are ready.", progress = "Your vision not Ohgan'aka's, no.\n\nYou are not ready.", completion = "What did Priestess tell you?\n\nThe raptor is daughter of Ohgan, heir to Mandokir's seat.\n\nHah!", objectives = "Speak with Priestess Thaalia at Fort Livingston to participate in the Mind Vision ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26774] = { id = 26774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mind Control", description = "Mind Vision is not enough, no.\n\nMind Control, much more powerful magic, yes.\n\nPowerful magic needs powerful reagents, and troll brain is a powerful reagent.\n\nBraddok in Zul'Mamwe, very smart, yes.\n\nHead south, and check out the big brain on Braddok.", progress = "Extra-big spells need extra-big brains, yes.", completion = "Hold on, next part is tough, yes.\n\nLots of chances to fail, yes.\n\nBut {name} and {name}'aka going to be reunited... yes they will.", objectives = "Obtain Braddok's Big Brain from Braddok in Zul'Mamwe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26775] = { id = 26775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Be Raptor", description = "Mind Control, very powerful, yes.\n\nWith luck, you can help Ohgan'aka escape from Zul'Gurub.\n\nThen, Ohgan'aka becomes {name}'aka again!\n\nSpeak to Priestess, yes, and help {name}'aka escape.", completion = "What a shame, yes.\n\nThis is what the spirits wanted, yes.\n\nMaybe when you are stronger, you will go into Zul'Gurub and take back your {name}'aka from Mandokir, yes.\n\nFor now, Priestess give you this.", objectives = "Speak with Priestess Thaalia, then help the Captured Lashtail Hatchling escape from Zul'Gurub.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26776] = { id = 26776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghaliri", description = "Priestess is not very good at speaking Common, no.\n\nMaybe you go speak with Ghaliri, in front of that tent.\n\nTell him about what you've seen inside Zul'Gurub, yes.", completion = "<You explain to Ghaliri what has happened up to this point.>\n\nIt would seem that Jin'do has survived, and he is rallying his brothers to once again summon Hakkar into this world.  It was good of you to come to speak with me.\n\nThere is not much we can do now but to wait, and watch.  Jin'do is weak, and prime for striking, but I must wait for word from Rastakhan before issuing orders.  Until then, you and your raptor will have to wait.", objectives = "Report to Ghaliri at Fort Livingston in Northern Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26777] = { id = 26777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soothing Spirits", description = "This is a tragic land, with a history of violence and despair. While many of the dead roam in the flesh, some are simply lost souls, wandering in confusion.\n\nThey deserve to be put at ease.\n\nMany of these souls gather at the Addle Stead to the south, appearing before travelers. Take this censer of holy incense. Sway it before the forlorn spirits, and let the offering of its gentle scent give them peace.", completion = "You have brought peace to those who knew only misery, {name}. Be proud.", objectives = "Use the Holy Censer to soothe 5 Forlorn Spirits at the Addle Stead.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26778] = { id = 26778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cries of the Dead", description = "Can you hear them, {name}? There's so many of them. They wander their graves, shuffling across the cold ground on rotting limbs.\n\nThe dead cry out in the still air. They suffer in their own flesh, forced from sleep! Every night I venture to the graveyard to put more of them to rest, but it's never enough.\n\nHelp me, {name}. Put the ghouls that swarm Raven Hill Cemetery out of their misery. Strike down as many as you can.", completion = "The cries grow softer for now. Light bless you, {name}.", objectives = "Kill 20 ghouls of any kind in Raven Hill Cemetery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26779] = { id = 26779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Mamwe Mambo", description = "The Skullsplitters are an embarrassment to the troll empire.  Their petty squabbles with the Bloodscalps have torn Northern Stranglethorn apart.  Where tribes like the Darkspear and the Zandalari thrive, the Skullsplitters fight over ruins.\n\nI have been authorized to issue rewards to mercenaries who are willing to deliver punishment to the Skullsplitters.  I encourage you, and anyone you know, to travel east into Zul'Mamwe and cull their wayward tribe.", progress = "Zul'Mamwe, though ruined, is still a defensible stronghold.  Take heed, {race}.", completion = "As promised, your reward.  You do the troll nation proud.", objectives = "Kill 16 Skullsplitter Trolls within Zul'Mamwe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26780] = { id = 26780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nighttime in the Jungle", description = "Nighttime in Stranglethorn is a beautiful thing.  The skies fill with stars, and the moon casts its rays right between those leaves, right there.  I could stare at these skies all night.\n\nUnfortunately, the trolls that walk the ruins of Zul'Mamwe are interfering with my astronomy.  They burn braziers, day and night, which rob me of the darkness I need.\n\nPlease, {name}... travel east into Zul'Mamwe and put them out.", completion = "I can see the difference already.  I can't wait until later tonight, when I get to perform my observations again!", objectives = "Put out 8 Zul'Mamwe Braziers at Zul'Mamwe in Northern Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26781] = { id = 26781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mind's Eye", description = "One of the Vale's many treasures lies nearby, on OUR side of the giant whirlpool.  The Mind's Eye is held by an ogre mage, in the Mosh'Ogg ogre mound just to the northeast.  His name is Mai'Zoth.  From what I understand, he is vicious, and his magic is strong.\n\nAnd if he has the Mind's Eye, then his magic will be stronger still.\n\nThus far I've been unable to get near enough to take it from him.  Will you give it a try?", progress = "Do you have the Eye?", completion = "You retrieved the eye!  Your might is the stuff of legends, {name}!\n\nAnd to think my brother and sister said we wouldn't find anything of worth here in the Vale.  Hah!  And I'm just getting started!", objectives = "Obtain the Mind's Eye from Mai'Zoth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26782] = { id = 26782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mosh'Ogg Bounty", description = "There's been some activity up north, at the rebel camp.  I just heard from a soldier named Nimetz that some {race} {class} up there found the key to what's been driving them so crazy.  That wasn't you, was it?\n\nAnyhow, he sent a sample to me, and it looks just like the rocks I've been seeing over at the Mosh'Ogg Ogre Mound, to the northeast.\n\nI've heard that the ogres are guarding a chest up in some ruins behind their mound.  I suspect it may be related.  Care to fetch it for me?", progress = "Why is it that the OGRES always find the priceless artifacts?", completion = "<Wulfred peers into the box.>\n\nThis... this is not like what I expected.  I had thought it would be a... a...\n\n<His eyes glaze over.>\n\nAhem!  I'm sorry.  I'm not sure what came over me.  I'll be sending this south, to the Explorers' League Digsite in the Cape.  Maybe they'll know what to do with it...", objectives = "Obtain the Mosh'Ogg Bounty from the ruins behind the Mosh'Ogg Ogre Mound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26783] = { id = 26783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mosh'Ogg Bounty", description = "There's been some activity up north, at the rebel camp.  I just heard from a soldier named Nimetz that a {race} {class} up there found the key to what's been driving them so crazy.  That wasn't you, was it?\n\nAnyhow, he sent a sample to me, and it looks just like the rocks I've been seeing over at the Mosh'Ogg Ogre Mound, to the northeast.\n\nI've heard that the ogres are guarding a chest up in some ruins behind their mound.  I suspect it may be related.  Care to fetch it for me?", progress = "Why is it that the OGRES always find the priceless artifacts?", completion = "<Wulfred peers into the box.>\n\nThis... this is not like what I expected.  I had thought it would be a... a...\n\n<His eyes glaze over.>\n\nAhem!  I'm sorry.  I'm not sure what came over me.  I'll be sending this south, to the Explorers' League Digsite in the Cape.  Maybe they'll know what to do with it...", objectives = "Obtain the Mosh'Ogg Bounty from the ruins behind the Mosh'Ogg Ogre Mound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26784] = { id = 26784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muddied Waters", description = "The elemental powers are strong here in the Highlands, {name}. It is why the Twilight's Hammer chose to build their stronghold here.\n\nIn the right hands, we can channel this energy into something productive... like a portal directly to Orgrimmar.\n\nNorthwest of here, at the Verrall River Delta, water elementals have been stirred up by the actions of our foes upstream. Destroy them and gather 5 whirlpool cores. You'll not only calm the river, you'll power up our portal.", progress = "I hope the fighting within the river wasn't too dangerous.", completion = "These are perfect! The restless waters of that troubled river will now do much more than move silt or stone... They'll move you across continents.\n\nFinish up the rest of your business here in Dragonmaw and then we should be able to proceed.", objectives = "Slay Muddied Water Elementals to collect 5 Whirlpool Cores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26785] = { id = 26785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Part of the Pack", description = "I've been trying to keep my true self hidden away from the people of Darkshire... they seem to react poorly to worgen. There are more of us here, though, beyond the city.\n\nThe companions I first traveled here with search the woods for wild worgen. They believe some of them, ones with telltale signs, can still be returned to sanity.\n\nI'm not quite ready to rejoin them. Please send word to Apprentice Fess at the crossroads west of town that I'll be staying in Darkshire a while longer.", completion = "Tobias is staying in town still?\n\nMaster Harris warned him not to pursue his brother's fate. We all lead new lives now, after all. But the past is hard to let go of...", objectives = "Speak to Apprentice Fess at the crossroads west of Darkshire in Duskwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26786] = { id = 26786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the Beach Head", description = "Something troubles me, {name}. The Twilight dragons knew just where and when to strike our airfleet. It's as if they knew our plans.\n\nTwilight spies cower within our midst!\n\nI'm going to take one of our remaining ships back to Orgrimmar to roll some heads. I need you to stay behind and secure this front. The Dragonmaw shaman are powerful; I have asked them to open up a portal to Orgrimmar, and I need you to help.\n\nSo. Start helping!", completion = "Your Warchief is decisive, {name}. He makes things happen. I like him.\n\nLet's talk about this portal that he wants!", objectives = "Speak with Artesh at Dragonmaw Port in Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26787] = { id = 26787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bear In Mind", description = "I'm afraid that... well, I'm just plain afraid, but I'm also sorry to have to ask for another favor.\n\nMaster Harris needs brains. Bear brains. They're part of the serum apparently, or at least a proper substitute.\n\nThere's plenty of black bears in the woods to the west, and along the riverbank, but... I can't do it! I'm too terrified to go out there and face those huge things, even with a rifle. Please, let me pay you to bring back some!", progress = "Did you get them? Did you?", completion = "Thank you! Oh, thank you. I never thought I'd be happy to smell those brains, but I am now that I didn't have to get them!\n\nHere's your reward as promised...", objectives = "Collect 8 Black Bear Brains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26788] = { id = 26788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cementing Our Victory", description = "Our alliance with the Dragonmaw is secured, but this port is far from combat ready. These flimsy wooden walls are an embarrassment to the Warchief.\n\nWhen water elementals carve their way through rock, as they have in the Verrall River, they create a peculiar kind of muck. It spreads easily and dries harder than the hardest stone. It's the perfect mortar for large-scale construction.\n\nGo to the river delta northwest of here and collect some Verrall River muck. Even a little will go a long way.", progress = "Do you have the mud? Construction of the new walls has already begun!", completion = "<Ornak allows the muck to drip from his fingertips.>\n\nNow that's the stuff! I'll start mixing and diluting this with gravel and water. Just a few handfuls of this can enhance enough cement for an entire stone tower.\n\nWe've got big plans for this port, {name}. You'll see!", objectives = "Collect 10 piles of Verrall River Muck.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26789] = { id = 26789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You no take axe!", description = "{name}, we have a problem! I've tracked down the demon-hound Magmadar to this clearing, but when we resting a band of kobolds took our battle axes! I need you to retrieve them, lest Magmadar catch us off guard! Hurry, he could awaken at any moment!", objectives = "Kill 5 Test Kobolds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26790] = { id = 26790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magmadar Must Die!", description = "There he is, {name}. The foolish beast fell asleep right out in the open! Good news for us, eh? Come, hero, we fight now! You can even have the honor of severing his head from his massive body. What's that? Too big for your bags? Why, carry it, of course! <Thrall grins.>", objectives = "Bring Magmadar's head to Thrall in Stonetalon Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26791] = { id = 26791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprout No More", description = "The stone trogg mystics are creating those fungal monstrosities from the giant mushrooms to the north.\n\nI want you to take a war guardian to help deal with the giants and stone troggs. Make your way to the giant mushrooms and target them. I and my geomancers will sink them into the ground before the mystics have a chance to finish their ritual.", completion = "They won't have any more of those fungal giants to throw against us!", objectives = "Interact with and gain a War Guardian, and destroy 5 Giant Mushrooms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26792] = { id = 26792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fungal Monstrosities", description = "Grab yourself a war guardian, and destroy those fungal monstrosities while you're out there.", completion = "Thank you, {name}. We've never had such a problem in Deepholm before the destruction of the World Pillar.\n\nYour Earthen Ring must repair the damage before it's too late.", objectives = "Slay 5 Fungal Monstrosities.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26793] = { id = 26793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Weathered Grave", description = "The weathered grave marker reads simply:\n\nMORGAN LADIMORE\n\n<Upon further examination, you notice that dirt over the grave has been recently disturbed, and that a good amount of the dirt seems to have been displaced...>", completion = "Morgan Ladimore?\n\nAhh, yes, of course. His was a long and sorrowful tale. I knew him, well, before he left for the war, but that was the last time I saw him. A noble and good man, he was, but he suffered a bad end.\n\nHere, I should have something here that can tell the tale better than my own recollections...", objectives = "Speak with Sirra Von'Indi in Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26794] = { id = 26794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgan Ladimore", description = "<He searches through the shelves and comes up with a leatherbound book.>\n\nIf you would like to know more, you might ask Althea, she's been the one to handle the... trouble... with him of late.", completion = "Morgan Ladimore? Never heard of...\n\nOh, you mean Mor'Ladim! I guess you haven't heard the story?\n\nWell, I'll give you the short version. A powerful undead calling itself Mor'Ladim has been wandering Duskwood. From what we've gathered, it appears to be the undead body of Morgan Ladimore, of whom you apparently know. He's been causing us all sorts of problems, attacking Watchmen on patrol and killing people.\n\n<She sizes you up.>\n\nYou seem to be capable enough, maybe you could lay him to rest.", objectives = "Speak with Commander Althea Ebonlocke in Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26795] = { id = 26795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'Ladim", description = "From what my scouts tell me, Mor'Ladim wanders throughout Duskwood, following a strange and meandering path through the cemetery. We buried him out past the house on the hill, you know where that is?\n\nThere isn't anything I can do to help you, but I wish you good luck.", progress = "I don't blame you if you're having trouble with him, {name}. Some of our strongest Watchers have been lost to Mor'Ladim.", completion = "You killed him? That's no small accomplishment, {name}! On behalf of the people of Darkshire and the Night Watch, I thank you.\n\nAh... there is one small matter, however...", objectives = "Kill Mor'Ladim, then return his skull to Commander Althea Ebonlocke in Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26796] = { id = 26796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Daughter Who Lived", description = "I should have told you this earlier...\n\nHow do I put this...\n\nMorgan may have believed that his family was all dead, but, in fact, his daughter Sarah Ladimore is now a Watcher. She's always been troubled by the... circumstances... surrounding her father's death. Perhaps you could go to bring the news to her.", completion = "Yes? My father...\n\n<Her eyes become downcast.>\n\nI wish... there was something I could have done for him... If only I had talked to him before he...", objectives = "Speak with Watcher Sarah Ladimore in Darkshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26797] = { id = 26797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Daughter's Love", description = "Here, take this and lay it on his grave. Maybe... somehow, he'll know that I'm okay, and that none of us hold him responsible for what happened.\n\n<There are tears in her eyes now, as she slides a ring from her right hand, and presses it into your hands.>\n\nAnd... thank you, {name}.", progress = "Leave me be...", completion = "<A ghostly voice sounds on the wind...>\n\nThis is...? Sarah? Could it be she's still alive? The weight is removed from my shoulders...\n\n{name}. Take my sword, Archeus. As my soul is put to rest, I have no more need for it. It was forged to do good, and though I have proved myself unworthy to hold it, perhaps you will carry on the Light through it.\n\nLys, my love...", objectives = "Take Sarah Ladimore's ring to Morgan Ladimore's grave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26798] = { id = 26798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saurfang Will be Pleased", description = "The portal is ready!\n\nIt's not powerful enough to transport an army, but we can maintain the connection long enough to allow important individuals to pass back and forth.\n\nSaurfang will want to know about our progress here. Walk through the portal to Orgrimmar, then deliver the news him.", completion = "{class}, you've returned from Dragonmaw. The portal is functioning then? Good.\n\nBefore you return to your work there, we've got some dirty business to clean up right here in Orgrimmar...", objectives = "Use the portal in Dragonmaw Port to go to Orgrimmar and report to High Overlord Saurfang.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26799] = { id = 26799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those That Couldn't Be Saved", description = "The val'kyr raise hundreds of corpses every day.  Agatha raised you just a few moments ago.  Not all are as lucky as you, however.\n\nSome maintain their free will, but live in constant fear and confusion.  They usually run off into the woods, cowering at their own reflections.\n\nOthers lose their minds completely, shambling about aimlessly.  They often turn to violence, and must be destroyed.\n\nThis is your task, {name}.  Destroy them, our former brothers and sisters though they might be.", progress = "You will not go far in this new life if you are unable to kill even the weakest, most brainless creatures, {name}.  Do not return until you have success to report.", completion = "Not even the power of the val'kyr was enough to save these creatures.  They were doomed from the beginning.\n\nI have obtained some equipment for you, {name}.  It's not much, but it will help.  Please, take your pick.", objectives = "Kill 6 Mindless Zombies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26800] = { id = 26800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recruitment", description = "We've been shipping in dead bodies from Silverpine, Hillsbrad... hell, anywhere we can get them from.  We can't, however, afford to ignore the bodies which are sitting right on our front doorstep.\n\nThe last vestiges of the Scarlet Crusade roam here in Tirisfal Glades.  While we've managed to push them from Deathknell, several of their bodies litter the buildings to the north and the east.\n\nGo find them... and bring that Darnell fellow with you.  He looks strong enough to carry a few corpses.", progress = "Have you managed to scavenge up some corpses?", completion = "Great work {name}.  I knew you weren't useless.\n\nHere, take one of these.  We deathguards have piles of these things just sitting around.", objectives = "Search Deathknell and the vicinity for 6 Scarlet Corpses, then point at them so Darnell can pick them up.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26801] = { id = 26801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scourge on our Perimeter", description = "If you're going to be an asset to the Forsaken, you need to learn how to fight.  And there's no better target than the Scourge minions that continue to pester us.\n\nThe wretched ghouls and Rattlecage skeletons that roam the north and to the east are former troopers of the fallen Scourge.  They should prove to be an even match for a fledgling {class} like you.\n\nDo not tarry - when you are done, speak to me again.", progress = "Those who dally in this task might as well end up wandering about aimlessly like our fallen brothers and sisters in the village.  Let's hope you will fare better than them, yes?", completion = "You're growing in strength, {name}.  I've seen your type before.  You will be moving out of Deathknell and on to greater things before long.  Just make sure you don't lose sight of where you started.\n\nYou have much to accomplish, {class}.", objectives = "Kill 8 undead outside of Deathknell. You may kill either Wretched Ghouls or Rattlecage Skeletons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26802] = { id = 26802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Damned", description = "First of all, look at your armor.  You're a mess, {class}.\n\nIf you'd like to stay in one piece--and I've no doubt you do--perhaps I can help.  If you can gather some paws and wings from the wolves and bats nearby, maybe I'll find some armor for you.  You'll find the creatures to the north and to the west of here.", progress = "Do try your best to keep yourself unharmed until I get you some armor.", completion = "Thank you, {name}. This armor should help you out.\n\nHopefully, it should do you more good than the last one to wear it...", objectives = "Obtain 4 Scavenger Paws and 4 Duskbat Wings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26803] = { id = 26803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Reports", description = "Saurfang is wise, and his intentions are good. In time, he will grow to see your people as a valuable ally.\n\nI am awaiting reports about recent Alliance activity in Durotar, but they haven't arrived yet. Would you be willing to visit Razor Hill and ask him for the reports in person? The easiest way to get there is by wind rider. Doras, Orgrimmar's wind rider master will let you use one of his wind riders for a small fee. Look for him on the rise north of the Valley of Strength.", completion = "So you need to get to Razor Hill in a hurry? That's no problem at all. One of my wind riders will get you there very quickly and it only costs a few coins to hire one.", objectives = "Talk to Orgrimmar's wind rider master, Doras.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26804] = { id = 26804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight to Razor Hill", description = "When you're ready to take the wind rider down to Razor Hill, simply speak with me again. When you get there, waste no time in finding Gar'Thok. He's the one responsible for preparing reports on recent Alliance activity in Durotar.", completion = "Eitrigg sent you? The warchief must be getting anxious to read my reports. I'd've sent them long ago, but each day we discover more about the Alliance's plans for invading Durotar.", objectives = "Speak to Doras to purchase a wind rider ride to Razor Hill. Once you arrive, speak with Gar'Thok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26805] = { id = 26805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Cape!", description = "The Explorers' League is growing, {name}.  Not only have they taken in worgen like me, but they have expanded their range in search of artifacts.  One of our best, Bronwyn Hewstrike, has set up a camp in the south, where he believes an item of titan origin may be hidden.\n\nBronwyn asked me to perform some duties here in the north, one of which was to identify potential recruits.  You seem to be made of the right stuff.  Talk to Robert Rhodes, the flight master, and he'll send you down there.  Bronwyn's treat.", completion = "Wulfred has a good eye.  I think you'll do just fine here at my camp.", objectives = "Speak with Robert Rhodes to obtain a flight to the Explorers' League Digsite in the Cape of Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26806] = { id = 26806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reports to Orgrimmar", description = "Eitrigg will have to be happy with the part of the report that I've finished. Tell him to expect more in the future.\n\n<Gar'Thok hands you a stack of roughly folded papers.>\n\nThis should cover the most important details of the increase in Alliance forces working out of Northwatch. Please apologize to Eitrigg for me and let him know that we've had our hands full here, trying to keep Razor Hill secure and supplied. When you're ready to return to Orgrimmar, simply speak to Burok and hire a wind rider.", progress = "Are you ready to return to Orgrimmar?", completion = "Ready to return to Orgrimmar with those reports? I can arrange a flight for you right away.", objectives = "Take Gar'Thok's Reports to Burok at Razor Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26807] = { id = 26807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Eitrigg", description = "Since you've already spoken to Doras, you'll be able to hire a wind rider to take you right back to Orgrimmar. Each time you arrive in a new town, be sure to speak with the town's flight master. After that, you'll be able to use the flight master's services to travel quickly.\n\nSpeak to me again when you're ready to purchase a return flight to Orgrimmar. Bring those reports to Eitrigg in the Valley of Strength once you've landed.", progress = "Did you bring those reports?", completion = "<Eitrigg examines the reports.>\n\nThe Alliance has grown bolder than we'd thought! I'll talk to the warchief about sending reinforcements right away. Thank you for getting these reports to me so quickly. I hope this coin is enough to cover your travel expenses.", objectives = "Speak with Burok and purchase a flight back to Orgrimmar. Once in Orgrimmar, bring Gar'Thok's Reports to Eitrigg in the Valley of Strength.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26808] = { id = 26808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maywiki", description = "<Linzi looks troubled.>\n\nYou know, there's a troll hiding behind that pile of boxes.  She must be awfully sad, if she doesn't want to come out and talk to anyone.\n\n<Linzi places some of the Akiris reeds in a kerchief and ties it together.>\n\nHere, give these to her.  They're very soft, and that maybe they will make her feel a little more comfortable back there.", progress = "Care to explain yourself, {class}?", completion = "<The troll looks into the package.>\n\nYou have my thanks.  You may tell your young dwarven friend that I am not sad.  I am waiting.  For you.\n\nI have identified you as the most promising {race} here in this strange town.  I have a task for you, if you would be willing to take it.", objectives = "Bring Linzi's Gift to Maywiki of Zuldazar at the Explorers' League Digsite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26809] = { id = 26809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Backdoor Dealings", description = "Zanzil the Outcast, an exile from the Gurubashi tribe, is my quarry.  Recently, I have heard tales from my brothers in the north about his planned reentry into society, starting with the emissary he sent to the Skullsplitters.  This is not good news.\n\nI want you to peer into Zanzil's current plans.  Take this incense, and place it in front of the bat totem in the Ruins of Jubuwal, to the north.  Hir'eek will guide you from there.", completion = "It is as I suspected.  Zanzil is too haughty to interfere with the squabbles between the Bloodscalps and the Skullsplitters.  No, he is playing a part in a grander scheme... Jin'do the Hexxer is using him to help bring Hakkar back to Zul'Gurub.\n\nIt's good that we found this out now, because it offers us a simple solution.", objectives = "Place the Gurubashi Incense in front of the Totem of Hir'eek, then listen to Zanzil's plot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26810] = { id = 26810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eliminate the Outcast", description = "You are to kill Zanzil.  You rode on Hir'eek's wings and saw through Hir'eek's eyes; you know where Zanzil hides within the Ruins of Aboraz.  Travel there and kill him.\n\nOh, and {race}: if we become separated, you should use this fetish.  It only works within Stranglethorn, but it will transport you back here to me should you need to return swiftly.\n\nGood luck, {race}.  Zanzil is no ordinary opponent.", objectives = "Travel to the Ruins of Aboraz in the Cape of Stranglethorn and deal with Zanzil the Outcast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26811] = { id = 26811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Troll Hole", description = "It looks like Zanzil's portal into Zul'Gurub is still open.  Zul'Gurub is a dangerous place, but Maywiki entrusted this task to you.\n\nThe portal lies in wait in front of you.", objectives = "Use Zanzil's Portal and enter Zul'Gurub.\n\nIf you become lost or need to return to Zul'Gurub, speak with Maywiki at the Explorers' League Digsite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26812] = { id = 26812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Priestess Jeklik", description = "Ahead of you looms a ramp up to one of the city's many terraces.  The bat-shaped totems ahead of you indicate that this is the domain of High Priestess Jeklik, a follower of Hir'eek.\n\nJeklik was one of the Hakkar-worshipping priests that Zanzil was planning to resurrect.  Perhaps if you hurry, you can stop the resurrection!", objectives = "Destroy High Priestess Jeklik's body before Zanzil can resurrect her.\n\nIf you become lost or need to return to Zul'Gurub, speak with Maywiki at the Explorers' League Digsite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26813] = { id = 26813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plunging Into Zul'Gurub", description = "Zanzil the Outcast has once again escaped through one of his portals.  Follow him!", objectives = "Pass through Zanzil's Portal.\n\nIf you become lost or need to return to Zul'Gurub, speak with Maywiki at the Explorers' League Digsite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26814] = { id = 26814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Priest Venoxis", description = "Venoxis was the second of the two priests that Zanzil planned to bring back from the dead.  You have already succeeded in destroying the body of High Priestess Jeklik... Venoxis must be the next.", completion = "I ask you to slay Zanzil the Outcast, a lowly, hermetic exile of the Gurubashi, and what do you do?  You dash headfirst into the Gurubashi capital and eliminate one of their High Priests!  Very nearly two!  Only one word suffices to explain such a rash and foolhardy endeavor:\n\nHeroism.\n\nJin'do the Hexxer still walks within Zul'Gurub's walls, but he lost one of his legs when you crushed Jeklik.  Today's battle is ours.", objectives = "Deal with Zanzil the Outcast and High Priest Venoxis.\n\nIf you become lost or need to return to Zul'Gurub, speak with Maywiki at the Explorers' League Digsite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26815] = { id = 26815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zanzil's Secret", description = "Years ago, the Gurubashi exiled one of their own from Zul'Gurub: a troll by the name of Zanzil.  The reasons why aren't all that clear, but I'd guess it had something to do with his tendency to administer powerful, behavior-altering drugs to anyone he saw.  Anyhow, the Gurubashi priests and their blood god have been slain, but Zanzil the Outcast remains...\n\n...as do his powerful, behavior-altering drugs.\n\nI need his mixture for my next test.  Check the zombies to the north.", progress = "Excellent... you're not a zombie yet.  That's good.\n\nOh, umm... nothing.  It's just that... that was a potential risk.  Did I forget to warn you?", completion = "<Dask carefully analyzes the strange compound.>\n\nThis mixture is... PERFECT!  Let's see what it does to your potentially-titan artifact here!", objectives = "Obtain 5 vials of Zanzil's Mixture.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26816] = { id = 26816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recipe for Disaster", description = "Did you see that explosion I made?  I must have flown 10 inches off the ground!\n\nI've just got to get Zanzil's recipe so I can find out why it did that.  One of Zanzil's flunkies at the Ruins of Aboraz must have it on him.  Head east, to the coast of the Cape, and snatch it for me!", progress = "Did he use shimmerweed?  I'm guessing he used shimmerweed.\n\nNo wait... amberseeds!  It's gotta be amberseeds.", completion = "This is fascinating!  Just think of all the applications!\n\nThanks again, {name}.  Remember, if you ever need anything mixed for you... and I mean ANYTHING... you can always ask The Flask.", objectives = "Obtain Zanzil's Formulation from one of Zanzil's followers in the Ruins of Aboraz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26817] = { id = 26817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfectly Pure", description = "This humour won't serve on its own.  Too thick.  WAY too thick.\n\nThe nagas to our west maintain a shrine that dispenses the only clean water this side of Duskwood.  For most potions, I'll use river water, but Bronwyn demands accuracy!\n\nObtain it from the Nek'mani Wellspring at the peak of the naga camp.  Good luck!", progress = "<Dask looks eagerly at your pack as you approach.>", completion = "Do you know how hard it is to get fresh water in Stranglethorn?  It's no wonder that the nagas guard their shrine so ferociously!\n\nAlright, let's get this mix started!", objectives = "Obtain The Holy Water of Clarity from the Nek'mani Wellspring in the Cape of Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26818] = { id = 26818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plush Pelts", description = "Hi, I'm the town merchant!  And Bronwyn's my dad!\n\nSorry, I shouldn't get too excited.  Father says it's not professional.\n\nAnyhow, people always come to me asking for heavy leather, or rough hides, but I think they might also like it if I had some soft materials... like tiger fur!  Think you could get some for me?\n\nYou'll find a few panthers nearby, but if you want to see the big tigers, you'll have to go northwest from here... north of that big troll arena.", progress = "Oooh... I hope they're soft!", completion = "<Linzi feels the hides and smiles to herself.>\n\nThese are so nice and cushy!  I think my customers are going to LOVE them!", objectives = "Obtain 4 Supple Tiger Furs and 4 Velvety Panther Furs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26819] = { id = 26819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akiris by the Bundle", description = "The naga explorers to our west carry a valuable ocean reed - Akiris reeds.  Traders use them to make medicines and poultices, and craftsmen use them to line armor or even wrap cigars!\n\nIn the evenings, when digging's done, father's been teaching me how to use them... but unfortunately, we ran out.  Would you mind getting us some more?", progress = "Welcome back!", completion = "Hooray!  It's been days and days since we last had Akiris reeds!", objectives = "Obtain 6 Akiris Reeds from Naga Explorers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26820] = { id = 26820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If They're Just Going to Leave Them Lying Around...", description = "Father says that a responsible merchant is always keeping an eye out for good deals.  I've been trying to look for deals everywhere I go, and I think I've just found one!\n\nThe naga to the west have dozens of statues that they place on the ground where they live.  They couldn't possibly need all of them... so I was thinking that we'd take some for ourselves!\n\nFree statues!  That's a good deal, right?", progress = "Let's see 'em!", completion = "These statues are beautiful...\n\nWow, I had no idea the naga were so talented.  Thanks, {name}!", objectives = "Obtain 6 Naga Icons from the Southern Savage Coast in the Cape of Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26821] = { id = 26821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Airwyn Bantamflax", description = "Well, we have no idea what this artifact is.  It's old, older than dirt... but not titan.  I'm completely dumbstruck.\n\nAirwyn Bantamflax in Booty Bay is my direct superior.  Our next step should be to inform her of this find.  Please, would you bring it to her?", progress = "Yes, {race}?  I'm quite busy.", completion = "Fascinating!\n\nI'll need some time to study this.  Why don't you have a look around Booty Bay and come back later?", objectives = "Bring the Opened Mosh'ogg Bounty to Airwyn Bantamflax at Booty Bay in the Cape of Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26822] = { id = 26822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good-Fer-Nothin' Slither-Dogs", description = "Ahem!  Hrm, hrm...\n\n<The dwarf clears his throat for several seconds.>\n\nYou're lookin' fer somethin' ta do?  And ya come askin' ME?  Lowly ol' Goris?!\n\nWell, ah... this is a first.  Ah, I've got it!\n\nThe vale ta tha north is filled with a bunch o' useless, belly-scrapin' basilisks.  They don't do nothin' for no one, and I hear they turned a guy ta stone once.\n\nIf ya kill 'em, I'll give ya some o' my stuff.", progress = "This is kinda fun.  Sendin' folks out ta do work for me... better than lousy ol' guard duty.", completion = "Ahem!  Ahhh... right...\n\nWell done!  And, congratulations, on killing them, I mean.\n\nHere you go.", objectives = "Kill 12 Thrashtail or Ironjaw Basilisks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26823] = { id = 26823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Too Big For His Britches", description = "Whatever it is you want to do: I've got a recipe that'll do exactly that.  You want an exploding potion?  BOOM!!  You want a lightning potion?  ZAP!!  You want a shrinking potion?  Smeerp.\n\nSo Bronwyn says he wants a carbon-dating potion?  Easy.  I could make that in my sleep.  The thing is... if we want it to be accurate, I need you to get some quality ingredients.\n\nStart with some humour from a basilisk to the north.  It'll need to be a pretty big basilisk...", progress = "You got the task?  I got the flask.", completion = "Alright!  Step one - getting ingredients - is all done.  Time for the next step: getting more ingredients.", objectives = "Obtain a vial of Ironjaw Humour from the Ironjaw Behemoth in the Crystalvein Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26824] = { id = 26824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Results: Inconclusive", description = "I did all I could, {name}.  I had the right potions... I had the right recipes... but the source of this sample eludes me.  It's tens of thousands of years old, but we've shown that it's not of titan origin.  And it's not saronite, I can tell you just by looking at it.  So... what in Brann's name is it?\n\nTell Bronwyn that I tried my best.  Sorry.", progress = "I saw smoke.  Everything alright?", completion = "I knew that alchemist was all talk.  Well, thanks for your help, {name}.  I know you tried.", objectives = "Return the Opened Mosh'Ogg Bounty to Bronwyn at the Explorers' League Camp in the Cape of Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26825] = { id = 26825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dask \"The Flask\" Gobfizzle", description = "Hey - you must be that <fella'/lass> that Wulfred was talkin' about!  The one who found the ogre artifact, and helped him test out those strange stones from up north.  Welcome to the digsite, {name}!\n\nWe were actually working on identifying those samples right as you got here.  Would you mind bringing the sample over to Dask?  I need him to help me find out how old it is.", progress = "You got something that needs mixing?", completion = "So once again, it falls upon tiny Dask to get the Explorers' League work done!  Alright... let's see what you've got in there.", objectives = "Bring the Opened Mosh'Ogg Bounty to Dask \"The Flask\" Gobfizzle at the Explorers' League Digsite in the Cape of Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26826] = { id = 26826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dask \"The Flask\" Gobfizzle", description = "Hey - you must be that <fella'/lass> that Wulfred was talkin' about!  Welcome to the digsite, {name}.\n\nWe were actually just starting a project when you arrived.  Would you mind bringing this sample over to Dask?  I need him to help me find out how old it is.", progress = "You got something that needs mixing?", completion = "So once again, it falls upon tiny Dask to get the Explorers' League work done!  Alright... let's see what you've got in there.", objectives = "Bring the Opened Mosh'Ogg Bounty to Dask \"The Flask\" Gobfizzle at the Explorers' League Digsite in the Cape of Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26827] = { id = 26827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rallying the Earthen Ring", description = "We must be rallyin' da Earthen Ring for dis fight. What we be lackin' in numbers, we make up for in strength.\n\nGo to tha temple and gather da restin' shaman from tha rear rooms. Norsala, Lorvarius, and I will be meetin' them at Lorthuna's Gate.", completion = "You've done what I thought not possible. Quite impressive, {class}.", objectives = "Rally 5 shaman in the rear of the Temple of Earth, and then speak to Maruut Stonebinder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26828] = { id = 26828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Part of the Bargain", description = "Sadly, I must stay and hold the rift, so you will have to battle without me. Go now to Therazane and join the battle, as promised. You should find her at the Halcyon Egress, north of Lorthuna's Gate and east of the Scoured Reach.\n\nWhen our part of the bargain is fulfilled, bring the last piece of the World Pillar here as quickly as possible.", completion = "And so you arrive, fleshling.  As promised.", objectives = "Speak to Therazane on the Halcyon Egress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26829] = { id = 26829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stone March", description = "My forces have already begun the assault. Join them. Spill the blood of these cultists upon the ground, that I might feel how they suffer.", completion = "Their blood upon the earth is a sweet thing. I shall cherish every moment, slowly extinguishing the stragglers from my realm.", objectives = "Kill 15 Twilight Precipice Cultists.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26830] = { id = 26830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traitor's Bait", description = "The Twilight's Hammer agents still lurk within the confines of Orgrimmar. I need someone I trust to collect the final evidence of treachery.\n\n<Eitrigg pulls you aside.>\n\nI suspect that Sauranok the Mystic is involved. I need you to uncover the truth, {name}.  The Twilight's Hammer has placed their agents within the ranks of the workers at the airship docks to spread their lies across the land. Speak with them. If you find evidence of Sauranok's guilt then show him what happens to traitors of the Horde.", completion = "Sauranok, Sauranok. His own visions worked against him. Twilight's Hammer probably corrupted him from afar. Bah! Weak! We'll speak his name no more.\n\nI told him you were investigating the airship docks, {name}. To flush him out. Yes, I used you as bait. You served your Horde well, and deserve a reward for outing this viper from our midst.", objectives = "Question Orgrimmar Skyway Peons around the Zeppelin Towers. Look for any Suspicious Peons. Try to flush out Sauranok the Mystic and kill him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26831] = { id = 26831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Flight", description = "Terrath wants you to make your way to the far end of the precipice to fight Zoltrik Drakebane. He is on his way there as well, but he thinks Zoltrik is likely to take to the sky.\n\nQuite an impression you seem to have made, little one. Have you ever mused that none of this would have happened if I had just stepped on you during our first meeting? Fate is a strange thing.", progress = "It is good to see you on the battlefield again.", completion = "It is good that you were here. I find my size to be inhibiting when it comes to dragon riding, strangely.", objectives = "Defeat Zoltrik Drakebane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26832] = { id = 26832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Therazane's Mercy", description = "There are two leaders among the Twilight that need to be killed.\n\nOne is a human by the name of Boldrich. Small, as you are. But still dangerous, as you also are.\n\nThe other is a priestess by the name of Lorthuna. She is wily and hard to corner. Strike swiftly and do not let her escape, or I promise you, you will regret it later.", completion = "You let Lorthuna escape? I warned you of this.\n\nStill, their forces are shattered and their resources cut off. There is little they can do to me or my allies.", objectives = "Defeat Boldrich Stonerender and High Priestess Lorthuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26833] = { id = 26833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Word In Stone", description = "You have done as I've asked of you, {race}. I shall honor my word. Gorsik will meet you at the temple with our piece of the World Pillar.\n\nFinish your ritual and bind the rift. After you have done such, tell your Earthen Ring to leave this place.\n\nYou however... you can stay for a time if you want. You've earned at least that.", completion = "Gorsik has arrived. All of the pieces of the World Pillar are here, thanks to you.\n\nWhat you have done for us is immeasurable.  These final moments shall be the most crucial.  I hesitate to ask more of you, but I'd like you to stay with us and see this through.\n\nThe Twilight's Hammer was devastated by your attacks, but not destroyed.  It's no stretch to assume they will try to stop us from completing our ritual.", objectives = "Speak to Maruut Stonebinder in the Temple of Earth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26834] = { id = 26834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down Into the Chasm", description = "Down below in Needlerock Chasm is where the mystics are sprouting all of these fungal monstrosities. I sent Slate Quicksand and a small force to deal with it, but they've run into a snag.\n\nYou remember the Arch Geomancer? Would you fly down there to the northeast and lend him a hand?", completion = "Good to see you again, {name}. Now we'll get somewhere.", objectives = "Speak with Slate Quicksand at Needlerock Chasm in Deepholm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26835] = { id = 26835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Slight Problem", description = "While you were out there, Pyrium Lodestone contacted me. He said that there is a matter of great urgency and that your assistance is needed immediately. Return to him at the entrance to Needlerock Slag to the southwest.\n\nI wish you luck with the rescue of the Stonefather and the recovery of the middle fragment.", completion = "{name}, we have good news and a slight problem....", objectives = "Return to Pyrium Lodestone at Needlerock Slag in Deepholm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26836] = { id = 26836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue the Stonefather... and Flint", description = "We found out where the Stonefather is being held and young Flint ran off on his own to rescue him!\n\nI don't have to tell you that this is bad. Flint is going to get himself captured as well, or worse!\n\nThe stone trogg chieftain, Bouldergut, is at the end of the ledges above Needlerock Chasm to the north.\n\nPlease, {name}, you must go after Flint and free the Stonefather before we lose them both!", completion = "{name}! You did it! How will we ever repay you?", objectives = "Free Stonefather Oremantle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26837] = { id = 26837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Explorers' League Digsite", description = "Say, {name}... you seem suitable.\n\nBronwyn Hewstrike of the Explorers' League has been asking for recruits at his digsite in the Cape of Stranglethorn.  Personally, I don't understand why he can't just go down to Booty Bay and find his recruits there... pirates are easily swayed by a couple pieces of gold.\n\nEither way... rumors are he's finally found something in that jungle.  I wonder what it is?", sourceObjective = "Report to Bronwyn Hewstrike at the Explorers' League Digsite in the Cape of Stranglethorn.Say, {name}... you seem suitable.\n\nBronwyn Hewstrike of the Explorers' League has been asking for recruits at his digsite in the Cape of Stranglethorn. Personally, I don't understand why he can't just go down to Booty Bay and find his recruits there... pirates are easily swayed by a couple pieces of gold.\n\nEither way... rumors are he's finally found something in that jungle. I wonder what it is?", sourceObjectiveStatus = "unverified-source-field" }
quests[26838] = { id = 26838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rebels Without a Clue", description = "Several years ago, Stormwind's Captain Kurzen brought a brigade into Stranglethorn Vale on a mission whose details are still murky.  Kurzen swiftly descended into madness, as did his men... except for a few rebels who made it their mission to undo the evils that Kurzen had wrought.\n\nAs I said, that was years ago.  I'm now hearing rumors that Kurzen is dead, but those rebels still persist at their rebellion.  If you wish to investigate, you'll find them at a camp on Stranglethorn's northern border.", completion = "Welcome to our camp, {class}.  You couldn't have arrived at a better time.", objectives = "Report to Lieutenant Doren at the Rebel Camp in Northern Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26839] = { id = 26839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Away From It All!", description = "Say, {class}, you look tired.  Carrying around that heavy wallet... er, I mean... heavy equipment... must be a strain on your poor {race} back.\n\nSassy Hardwrench has recently established a premier five-star resort on the sparkling coast off the Cape of Stranglethorn.  Balloon tours, rowboating, day trips to Booty Bay... they've got it all.\n\nYou should really go visit.  I can tell just by looking that you need a break after so many difficult, lucrative adventures.", sourceObjective = "Visit Sassy Hardwrench at Hardwrench Hideaway in the Cape of Stranglethorn.Say, {class}, you look tired. Carrying around that heavy wallet... er, I mean... heavy equipment... must be a strain on your poor {race} back.\n\nSassy Hardwrench has recently established a premier five-star resort on the sparkling coast off the Cape of Stranglethorn. Balloon tours, rowboating, day trips to Booty Bay... they've got it all.\n\nYou should really go visit. I can tell just by looking that you need a break after so many difficult, lucrative adventures.", sourceObjectiveStatus = "unverified-source-field" }
quests[26840] = { id = 26840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Highlands", description = "With Orgrimmar secure and our Dragonmaw allies behind us, we can turn our attention to the conquest of the Twilight Highlands and the utter destruction of Deathwing's forces there.\n\nI need the Horde's best on the front lines. That means you. And all your friends.\n\nThe Highlands WILL be ours!\n\nUse the new portal you created to return to Dragonmaw Port. Report to Zaela to see where she needs you the most.", completion = "{name}! I trust Orgrimmar fares well?\n\nAs you can see, construction of Dragonmaw Port continues at a breakneck pace. If my people questioned the Horde's power before... the sight of this imposing edifice and the speed in which it was constructed leaves no doubt.\n\nA new day dawns for the Dragonmaw.", objectives = "Use the Twilight Highlands Portal in Orgrimmar to return to Dragonmaw Port in the Twilight Highlands and speak to Zaela.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26841] = { id = 26841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forbidden Sigil", description = "This sigil was given to me by a messenger from our mage trainer, Rhyanda. It seems Rhyanda would have words with you when you have a moment. Read it and bring it to her afterwards.", progress = "I'm glad that you've come, {name}.", completion = "I will be your mentor and guide for now. It is my duty to teach you the arcane arts and how you might best fit in among our people.\n\nAs you learn and grow in power, you will learn an immense variety of spells that should allow you to deal with nearly any situation. But until then, return to me as often as you like and I will teach you what I can in the ways of our kind.", objectives = "Speak to Rhyanda inside Aldrassil in Shadowglen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26842] = { id = 26842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Gnoll-where", description = "Well met, {class}. We've got a problem, and I'd ask you to lend a hand.\n\nIt's gnolls. There's a mess of the things west of town, roaming the hills. Not usually any cause for alarm, but we've not usually had gnolls here in Loch Modan.\n\nI'm curious where they came from, but not curious enough to bother asking the mangy things. Clear 'em out, I say. Bring back proof of your kills and I'll pay a solid bounty.", progress = "Got some ears for me, then?", completion = "Nicely done, lad. I could use a {class} like you around here.", objectives = "Collect 12 Gnoll Ears from Mosshide Scouts or Mosshide Bashers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26843] = { id = 26843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tiny, Clever Commander", description = "We've dealt with kobolds in these lands for years. Not much other than a nuisance. But they've been getting craftier at their stealing.\n\nI think one of them's ended up smarter than usual. Won't be that way for long, though!\n\nI want you to go to the camp south of here and make sure there's not a \"big shot\" kobold stirrin' up the other ones. Make sure to check the cave; it's a likely spot.\n\nAnd don't be shy about clearing out the other kobolds along the way.", progress = "Don't forget to find that \"commander\" down in the cave.", completion = "So I was right! Now the question is what the little freaks were plotting...", objectives = "Slay Commander Nazrim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26844] = { id = 26844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kobold and Kobolder", description = "Now that those little blighters are dealt with, we've got more to take care of.\n\nThe tunnel rats are swarming all over the Silver Stream Mine, setting up camps and sniffing around further and further every day. Greedy little things are looking for loot, I gather.\n\nSurveying and foraging is all fine and dandy when it's not on dwarven land! Take care of those tunnel rats and report back to me.", progress = "We'll deal with the mine proper once you've cleaned up the outer perimeter.", completion = "Good, good. Now we can see what's going on down in that mine.", objectives = "Slay 5 Tunnel Rat Surveyors and 5 Tunnel Rat Foragers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26845] = { id = 26845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who's In Charge Here?", description = "Dorli's filled me in on this crazy trogg-slave operation the kobolds have going, and if you haven't talked to her about it yet, I suggest you do.\n\nI'd like to get to the bottom of this. Literally! Whoever's running this show is bound to be at the bottom of the mine, calling the shots, and I want them dealt with.\n\nFind whatever crafty bugger is directing the geomancers and diggers and bring me back their head.", progress = "I don't suppose it was Moira down there? Miracles do happen.", completion = "That's a gnoll head. Are you trying to pull some funny business, {name}?\n\nIf you're not, I've not the faintest idea what's going on here.", objectives = "Collect the head of Foreman Sharpsneer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26846] = { id = 26846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Nasty Exploit", description = "I've found out what those rats are up to. There's so many of them outside because they've got troggs digging for them in the mine!\n\nThe tunnel rat geomancers figured out some kind of parlor trick to control the troggs, as creatures of the earth or somesuch.\n\nFascinating, but not something we want to let them practice. Take out those geomancers right away.", completion = "I'm sure that only worked because the troggs aren't bright to begin with. But then again, us dwarves were once creatures of the earth as well.\n\nBeing bossed around by a kobold doesn't sound quite dignified, and I'm glad we didn't get to find out if they could pull that off.", objectives = "Slay 5 Tunnel Rat Geomancers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26847] = { id = 26847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Quaking Fields", description = "The king has moved south, just past Stonehearth, to the Quaking Fields.\n\nGood luck in retrieving the middle fragment of the World Pillar, but beware the giants and other creatures of the field, {name}.", sourceObjective = "Speak with King Oremantle at the Quaking Fields in Deepholm.", sourceObjectiveStatus = "unverified-source-field" }
quests[26848] = { id = 26848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "X Marks the Spot", description = "<The king marks a spot on your map.>\n\nThat's where I buried it. Head on out there and dig it up for me.\n\nJust avoid those giants. I can tell you from experience that they hit like a... well, like a giant!", objectives = "Head out to where King Oremantle buried the second World Pillar fragment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26849] = { id = 26849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Axe of Earthly Sundering", description = "The emerald colossi need to be removed from the field. It's conceivable that one of them has the fragment. Regardless, Therzane has moved her forces too close to Stonehearth and they pose a threat.\n\nSunder the giants with my axe. That should bring them down to a more manageable size so that you can finish them off.You will be able to choose one of these rewards:", objectives = "Slay 5 Sundered Emerald Colossi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26850] = { id = 26850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Ore", description = "We'll need to perform a ritual to pinpoint where the World Pillar fragment's been taken.\n\nGo out into the field and collect elemental ore from the ragers. With enough of it, I should be able to make you one with the ground to learn what we need.", objectives = "Collect 6 Elemental Ore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26851] = { id = 26851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One With the Ground", description = "I know a ritual of the earth that will make you one with the ground. Because I have already handled the fragment, the spirits of the ground will take you near to it.\n\nKeep your mind focused on the World Pillar and let me know when you are ready, {name}.", objectives = "Through the One With the Ground ritual, discover the location of the Middle Fragment of the World Pillar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26852] = { id = 26852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fragment's Inside", description = "The Middle Fragment of the World Pillar is within Avalanchion's Vault. Enter and retrieve it.", objectives = "Collect the Middle Fragment of the World Pillar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26853] = { id = 26853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Middle Fragment", description = "Fly. Fly as fast as you can, {name}!\n\nGet the middle fragment back to the Temple of Earth in the middle of Deepholm!", objectives = "Deliver the Middle Fragment of the World Pillar to Earthcaller Yevaa at the Temple of Earth in Deepholm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26854] = { id = 26854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Pilot", description = "My friend and fellow Siege Engine pilot, Mori Hildelve, is lost in the hills. We were looking for a rare ore that's needed for a high-grade blastpowder, and during our search he drove his engine up a steep hill and busted it!\n\nStill convinced that ore was in these mountains, Hildelve charged me to guard our engines while he continued on foot.\n\nIt's been days, and I've heard some beastly growls north of Helm's Bed Lake, west of the tunnel. Mori's tough as nails, but I'm worried.\n\nPlease, {name}. Find him.", completion = "Here is the corpse of a dwarf -- mauled, frozen, and picked clean by mountain scavengers.  Clutched in its hand is a book containing the roughly scribbled notes of Mori Hildelve.  And around its frame, still in superior condition, is a Brigadier's Vest.\n\nThis grisly scene must have been where the Siege Engine pilot met his end.", objectives = "Find Pilot Hildelve north of Helm's Bed Lake.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26855] = { id = 26855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pilot's Revenge", description = "Hildelve wrote in his journal that he was attacked by Mangeclaw, a \"huge Ice Claw Bear.\"  He drove off the beast, but not before it mauled him savagely.\n\nJudging from the state of Hildelve's body, Mangeclaw must have later returned and killed him.\n\nHowever, Hildelve wrote in his journal his one, final wish:\n\nRevenge against Mangeclaw.", progress = "Hello, {name}.  Do you have word of my friend Hildelve?", completion = "This is grim news, for Hildelve was a good friend.  And I wish I could have been there with you when you found the beast, Mangeclaw!\n\nThank you, {name}. Your deed will be remembered by the pilots of the Ironforge Siege Brigade.", objectives = "Kill Mangeclaw.\n\nBring his Mangy Claw and Hildelve's Journal to Pilot Hammerfoot at the South Gate Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26856] = { id = 26856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repel the Invasion", description = "This cavern was once a place of great honor. Young warriors were taken here to slay an Earthborer worm for their first kill - something we Orcs remember for our entire lives.\n\nThe Burning Blade agents inside have enslaved the cave's inhabitants and plan to launch a full-scale attack on Orgrimmar along with their Trogg allies.\n\nIf you strike down their Lieutenants, you may be able to catch them unprepared and stop this invasion before it starts.", completion = "You've done it, {name}! You've upturned the Searing Blade's invasion before it could even start! Take this, as a token of my thanks.", objectives = "Kill Oggleflint, Bazzalan, and Jergosh the Invoker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26857] = { id = 26857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abyssion's Minions", description = "If it's the dragon that's got the fragment, we're going to need to draw his attention back to his den.\n\nGo to Abyssion's Lair just east of here and defeat his underlings.  That should get him to show up with the World Pillar fragment sooner or later.", completion = "That ought to get the dragon's attention, {name}.", objectives = "Defeat 8 Twilight or Dragonkin units at Abyssion's Lair.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26858] = { id = 26858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taragaman the Hungerer", description = "The Searing Blade has managed to summon a foul demon they call Taragaman the Hungerer to lead the first attack in their takeover of Orgrimmar!\n\nMake haste and slay Taragaman in the name of the Warchief! Lok'tar ogar!", progress = "If Taragaman is dead, show me his heart.", completion = "My children will sing songs of your glories, {name}!", objectives = "Take Taragaman the Hungerer's heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26859] = { id = 26859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Searching for the Lost Satchel", description = "The troggs are not the only thing that interested Magatha in Ragefire Chasm. She has heard word that one of her servants, a Maur Grimtotem, found something peculiar while in the Chasm, but he never made it out to show her what. She'd like Maur's body found--if it still exists--and any signs of what he found while attempting to speak to the troggs.\n\nReturn to Magatha any items of interest, and I'm sure she would be very generous in her reward.\n\nAgain, seek the Chasm in the darkest areas of Orgrimmar.", sourceObjective = "Search Ragefire Chasm for Maur Grimtotem's corpse and search it for any items of interest.", sourceObjectiveStatus = "unverified-source-field" }
quests[26860] = { id = 26860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thelsamar Blood Sausages", description = "There's never a shortage of empty bellies here in Thelsamar, kids running in and out, workers from the excavation coming in after a hard day's work. We're famous for our blood sausages, I don't suppose you've ever tried them?\n\nNo? Well, around here you've got to work for your meals, and don't think just because you're a fancy {class}, you'll be any exception.\n\nYou get me some fresh bear rumps and leave the cooking to me!", progress = "I'm all ready to start cooking, do you have the bear meat for me?", completion = "Much obliged! The rump's part of my own secret twist on the recipe... but here's instructions on how to make it with any kind of bear meat.\n\nAnd here's a fresh batch of me own. Mind you eat them fresh!", objectives = "Collect 8 Bear Rumps from Black Bears in Loch Modan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26861] = { id = 26861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Block the Gates", description = "If we're to have a shot against Abyssion, we must make sure he receives no aid from reinforcements.\n\nYou will find two gateways in his lair to the east.  Use this stormstone to disrupt their operation.\n\nIf everything goes as planned, we'll be able to tackle Abyssion without him being able to receive much assistance.", completion = "Excellent.  When we make our move against Abyssion, we should be able to do so without reinforcements coming to his aid.", objectives = "Use the Stormstone at the Twilight Gate and Elemental Gate in Abyssion's Lair.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26862] = { id = 26862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Tampering", description = "The Searing Blade's warlocks have enslaved Ragefire Chasm's elemental spirits, {name}. They aren't a threat to the city while my spell keeps them at bay, but I can't maintain it much longer.\n\nBring me six of the Searing Bindings used to control them and I will release their spirits back into the Chasm.", progress = "Do you have the bindings?", completion = "Thank you, {class}. The Molten Elementals' spirits are finally back to rest.", objectives = "Obtain 6 Searing Bindings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26863] = { id = 26863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filthy Paws", description = "The Silver Stream Mine to the east ran dry long ago. It was converted by the Miners' League into a storage depot, but now kobolds have moved in, putting their filthy paws on good, dwarven tools!\n\nWe'll root out those vermin soon enough, but the League wants someone to get their gear out of the mine before we warriors tromp in there and break things.  It'll be a tough delve - you might want cohorts at your side.\n\nThe gear is stored in Miners' League Crates throughout the mine.  Good luck.", progress = "Do you have that Miners' Gear, {name}?", completion = "Did you see a lot of kobolds in there? The thought of their grimy hands clawing around our mine makes my stomach rumble!", objectives = "Collect 6 loads of Miners' Gear from the Silver Stream Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26864] = { id = 26864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bearer of Gnoll-edge", description = "I need you to take this back to Mountaineer Kadrell. Show it to him and tell him the nasty critters around here might be having some kind of get-together.", progress = "Any news from Algaz Station?", completion = "Gnolls and kobolds, and troggs? Oh my.\n\nI'd laugh if I didn't have another twist in the story for you.", objectives = "Deliver Foreman Sharpsneer's Head to Mountaineer Kadrell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26865] = { id = 26865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Below", description = "There are enemies of the Horde beneath this very city, {class}.\n\nThe Searing Blade plots to take Orgrimmar for their own, and have already taken Ragefire Chasm! We need to storm their forces and retake what is ours!\n\nGo speak with Stone Guard Kurjack just inside Ragefire Chasm. He will have further orders for you.", completion = "I've been expecting your arrival, {name}.", objectives = "Speak with Stone Guard Kurjack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26866] = { id = 26866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Below", description = "Orgrimmar's Ragefire Chasm has been taken by the Searing Blade. {name}, we cannot allow this to pass unpunished, lest they next set their sights on Thunder Bluff.\n\nGo speak with Stone Guard Kurjack just inside the Chasm. Help him in any way you can, for our fates are intertwined.", completion = "I've been expecting your arrival, {name}.", objectives = "Speak with Stone Guard Kurjack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26867] = { id = 26867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Below", description = "With all his usual grace, Warchief Garrosh has kindly requested your presence in Ragefire Chasm to help retake it from the Searing Blade. Apparently, his reinforced city isn't as impenetrable as he thought.\n\nGo speak with Stone Guard Kurjack just inside Ragefire, I'm sure he'll be glad to have competent help.", completion = "I've been expecting your arrival, {name}.", objectives = "Speak with Stone Guard Kurjack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26868] = { id = 26868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Axis of Awful", description = "Alright, now just shut yer gob and lemme talk, 'cause here's the plan.\n\nThose gnolls and murlocs are liable to be meetin' out there somewhere. So you take this clever plant disguise of mine, and you wear it and look like a plant. Then you sneak up on 'em, and you throw this scent pheromone you gathered on the mosshide standin' with the murlocs.\n\nThen the murlocs'll flip their spit, and the mosshides will think twice about trying to work with such crazy lil' buggers!", progress = "Well don't just stand around here like some kinda idiot! Get out there and act like a plant!", completion = "Worked like a charm, didn't it? Maybe Kadrell will get off my darn back now what with savin' the whole town and all!\n\nI suppose you've done earned yourself some proper goods.", objectives = "Use the Clever Plant Disguise Kit to sneak up on the Mosshide Representative and use the Potent Murloc Pheromones on him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26869] = { id = 26869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Depth of the Depths", description = "<The ground trembles slightly, and the low, familiar voice of Diamant speaks as if from the stone itself.>\n\nWell done, {race}.\n\nWithin the tunnels below, you will find the stone which you seek. Painite.\n\nThe dangers ahead are many...\n\nDangers that the Stone Lords themselves fear.\n\nRemain steady.\n\nRemain strong.\n\nThe strength of the rock itself is beneath your feet.", completion = "<This is it. This is the stone Diamant sent you for.>", objectives = "Find the Painite within the Crumbling Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26870] = { id = 26870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing the Caverns", description = "Naralex had a noble goal.\n\nOur great leader aspired to enter the Emerald Dream and help regrow these harsh lands back into the lush forest it once was.\n\nBut something went terribly wrong.\n\nNaralex's trusted allies, the Druids of the Fang, turned on him! They seek not to heal the Barrens, but to dominate it.\n\n{name}, before we can awaken Naralex and restore balance to this vital place, you need to eradicate the Fanglords. Their influence has sunk too deeply.", progress = "Are the Fanglords dead? Muyoh cannot awaken Naralex until they are!", completion = "I can already feel the balance returning! Quick, talk to Muyoh to help him awaken Naralex!", objectives = "Ebru in the Wailing Caverns wants you to kill the Fanglords Cobrahn, Anacondra, Pythas, and Serpentis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26871] = { id = 26871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rock Amongst Many", description = "<The ground trembles slightly, and the low, familiar voice of Diamant speaks as if from the stone itself.>\n\nYou've done as I've asked.\n\nTurn back and escape the cave in one piece.\n\nDon't forget the gemstone.", progress = "You're alive. This is good.\n\nIs the gemstone with you?", completion = "Well done, fleshling!\n\nThe gyreworms are among our most dangerous enemies.\n\nThe other Stone Lords shall have trouble not turning their head to this accomplishment.", objectives = "Return to Diamant at Lorthuna's Gate with the Painite Chunk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26872] = { id = 26872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deviate Hides", description = "As Naralex descended deeper into his nightmare, a strange breed of beasts arose from beneath the Barrens into the Wailing Caverns.\n\nThese deviate creatures have strange, otherworldly properties. Their very existence causes great pain to the earth. I believe that slaying them will greatly aid our work in healing the caverns.\n\nIf you feel up to the task, slay as many as you can and bring me their hides as proof of their demise.", progress = "How many of the beasts have you slain?", completion = "Your efforts shall not go unnoticed, {name}.\n\nThank you for your dedication.", objectives = "Nalpak wants 10 Deviate Hides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26873] = { id = 26873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preemptive Methods", description = "There is an herb in these caverns that holds untold power, {name}. Perhaps you wish to help me collect it?\n\nIt is a rare flower called Serpentbloom. I believe that in greater quantities it has the potential to prevent nightmares like Naralex's from ever occuring.\n\nUnfortunately, Serpentbloom can only be found in the darkest recesses of this place.", progress = "I am eager to see if you can gather enough Serpentbloom.", completion = "You have done well, {name}. Hopefully we can use these to prevent further nightmares.", objectives = "Nalpak wants you to collect 5 Serpentbloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26874] = { id = 26874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Awakening Naralex", description = "Now that the Fanglords are dead, speak with Muyoh. He will help you awaken Naralex and end this nightmare.", sourceObjective = "Speak with Muyoh.", sourceObjectiveStatus = "unverified-source-field" }
quests[26875] = { id = 26875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undying Twilight", description = "The Twilight Cultists are here! They're trying to stop the ritual! Get to the back chambers and help fight them off!", completion = "The Twilight forces continue to stream in, but it looks like the Earthen Ring defenders can handle them.", objectives = "Kill 12 Twilight invaders and 1 Desecrated Earthrager.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26876] = { id = 26876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The World Pillar Fragment", description = "It is time, {name}.  We have spotted Abyssion making his way to the lair.\n\nThe Twilight's Hammer might've thought the fragment would be safe if a dragon guarded it, but I've met enough dragons to know their one weakness.  Pride.\n\nAbyssion's not going to run from a fight with us puny mortals.\n\nPlace the banner of the Earthen Ring in the middle of his lair.  Once we defeat him, bring the fragment to Maruut.  We need to repair the World Pillar as soon as possible.", progress = "{name}!  You've returned!", completion = "Your efforts in repairing the World Pillar are invaluable, {name}.  Once the Temple of Earth's structure is stable again, the rift between the worlds will begin to stabilize.", objectives = "Place the Earthen Ring Banner in the center of Abyssion's Lair, slay him and obtain the Upper World Pillar Fragment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26877] = { id = 26877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fragment's Inside", description = "{name}, you need to enter Avalanchion's Vault to the southeast and retrieve the Middle Fragment of the World Pillar!", objectives = "Collect the Middle Fragment of the World Pillar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26878] = { id = 26878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disciples of Naralex", description = "{class}, the Barrens used to be one of the most beautiful places in all of Kalimdor. It teemed with life and promise.\n\nNow, as you can see, that is no longer true. It is a land of great torment and strife.\n\nThe Disciples of Naralex seek to cleanse the Wailing Caverns and bring them back to their former beauty. Speak with Nalpak just inside the Wailing Caverns to help.", completion = "Yes, {class}? What brings you to this place?", objectives = "Speak with Nalpak in the Wailing Caverns.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26879] = { id = 26879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disciples of Naralex", description = "{class}, this place is, shall I say, not optimal for my business endeavors. If it were more lively, I have an idea that would make me the richest goblin that's ever lived!\n\nA {class} of your stature must see the potential in that, or at least care about the environment or something.\n\nGo talk to Nalpak just inside the Wailing Caverns, he's a Disciple of Naralex and, just between you and me, I think they're going to fix this blasted place for good! It's my big break!", sourceObjective = "Speak with Nalpak in the Wailing Caverns.", sourceObjectiveStatus = "unverified-source-field" }
quests[26880] = { id = 26880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gilneas City Unphase Cheat" }
quests[26881] = { id = 26881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Aluwyn", description = "There's something sinister going on within this place, {name}. We fear that the rumors of the Twilight's Hammer in Blackfathom Deeps are true.\n\nI sent Sentinel Aluwyn, one of our best scouts, further in to investigate the matter, but she hasn't returned.\n\nSeek her out. If she's still alive, find out all that she's learned.", sourceObjective = "Seek out Sentinel Aluwyn at Blackfathom Deeps.", completion = "Ashelan was good to send you. There is indeed a wicked plot underway in this corrupted place.", sourceObjectiveStatus = "unverified-source-field" }
quests[26882] = { id = 26882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackfathom Villainy", description = "My strength has left me. I need your help!\n\nLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from below and tainted the sacred moonwell.\n\nAku'Mai, a servant of the Old God, rose from the waters.\n\nThe Twilight's Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku'Mai for power.\n\nSlay Kelris and bring his head to Ashelan.", progress = "It is good to see you again, {name}. What news do you bring?\n\nWas your foray successful? Did you find Thaelrid?", completion = "Kelris has eluded us for quite some time.\n\nIt seems as though whenever evil made its presence known in these parts, Kelris had played a role. For some time we considered him either dead or missing.\n\nBut this makes perfect sense. By ending his reign you have spared the lives of many innocent people.\n\nTo sacrifice someone to a servant of an Old God for one's personal gain is beyond reproachful!\n\nYou have done a great deed, {name}. I thank you on behalf of Ashenvale.\n\nIf only Thaelrid had survived....", objectives = "Get the head of Twilight Lord Kelris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26883] = { id = 26883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Falls", description = "Empowered by the ancient rites of the chaotic Old Gods, the members of the Twilight's Hammer strive to bring about the return of their dark patrons and spread death and terror across the world.\n\nWe believe that the Twilight's Hammer has allied with the naga and are amassing here.\n\nWhatever evil plan brews in the depths of the old temple must be thwarted.\n\nWage war on the Hammer and bring back proof of your deeds. Your efforts will be rewarded handsomely.", progress = "Blackfathom Deeps was once an ancient night elf temple. It once housed a most powerful moonwell. Who knows what evil brews there now at the hands of the Twilight's Hammer.\n\nHave you made any progress in ridding the temple of their presence?", completion = "You are no doubt of brave and noble blood, {name}. We and all of the people of Ashenvale commend you for your efforts against evil.", objectives = "Obtain 3 Twilight Pendants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26884] = { id = 26884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Researching the Corruption", description = "Foolish blood elves toil with demonic magic. Have they not witnessed what happened with the naga and with the satyrs of Kalimdor?\n\nI fear that the blood elves will meet a similar deformation. Azeroth cannot afford to give birth to another vile race of monsters.\n\nI wish to study the brain stems of the satyr and naga so that I might deduce what fate the sin'dorei are headed toward. Try to avoid harming the stems while you kill them, I won't take anything but perfect specimens.", progress = "Once I have enough samples to study, my true work can begin. With the corrupted brain stems of both the satyr and naga of Blackfathom Deeps I can try to draw a correlation between the mutations.\n\nPerhaps with that gained knowledge we can prevent the blood elves from delving deeper into deformity and evil.", completion = "You have undoubtedly faced great peril to obtain these.\n\nYour actions have been selfless. It is for the good of all Azeroth that you help me with my research. I thank you, {name}, for all that you have done.\n\nNow if you'll excuse me I have much work to do.", objectives = "Gather 8 Corrupt Brain Stems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26885] = { id = 26885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knowledge in the Deeps", description = "It is my duty as a trainee to collect lore for my superiors. Old lore. Powerful lore. Lore that opens doorways, and lore that could awaken more of Those Who Sleep if it is mishandled.\n\nThere are rumors of an old piece of lore, the Lorgalis Manuscript, at the bottom of the Pool of Ask'ar in a Pitted Iron Chest. It is the old dwelling of our long-dead ancestors. They held great knowledge before their city fell to ruin.\n\nSearch for the manuscript, please. I'm not skilled enough to venture further!", progress = "Your task is not an easy one, my friend.\n\nBut if you get me the manuscript, {name}...then your reward will be great and we will gain a better understanding of what it is that the Twilight's Hammer and the naga are up to.", completion = "You found the manuscript! What a joyous day this is! I will study it exhaustively and learn all there is to know.\n\nI'll make full sentinel yet!\n\nYour service to us is more than you know, {name}. I hope that this gift shows you my gratitude.", objectives = "Find the Lorgalis Manuscript.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26886] = { id = 26886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going Off-Task", description = "That nasty ship on the east side of the cove keeps firing its cannons at us. It's kinda funny seeing all the goblins get hit by cannonballs, but some of my gnome friends are being hit too!\n\nIt'd be really, really nice if you could make your way past those cannons and onto the ship. There's a mean ol' taskmaster yelling at the other deckhands in there, and I'm sure if you beat him up or kill him, they'll stop shooting at us!", completion = "Wonderful! I hope you didn't get hit with too many cannonballs.", objectives = "Kill the Southsea Taskmaster.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26887] = { id = 26887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filling Our Pockets", description = "I know we're here to make friends with the Steamwheedle goblins, but those awful Bilgewater goblins are so rude.\n\nWhy, I just saw a bunch of them pulling gold fillings out of the teeth of the Southsea musketeers and strongarms. Do they think they can just take that for themselves?\n\nObviously, the nice thing to do is kill those pirates ourselves, take their fillings, and then give some of them to the Steamwheedle as a thank-you gift! Head on down there and beat those goblins to the punch.", progress = "Have you got the fillings?", completion = "More gold! We'll be sure to give some of this to Mister Noggenfogger to smoothly ensure our continued relations.\n\nAnd only a little bit of it will go back to Gnomeregan for experimental weapons development!", objectives = "Collect 20 Gold Fillings from Southsea Musketeers or Southsea Strongarms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26888] = { id = 26888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nightmare of the Deeps", description = "In the darkest recesses of Blackfathom, a monster spawned by the Old Gods lurks. We know it only as Aku'mai.\n\nThe Old Gods and their servants are incredibly dangerous to our world. Long ago, they ruled over Azeroth and I fear that they seek to do so again, or destroy it while trying.\n\n{name}, Aku'mai is a creature of untold nightmare. We simply cannot allow his continued existence. Destroy him.", completion = "The beast is slain. I can feel his dark presence fading away forever.", objectives = "Kill Aku'mai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26889] = { id = 26889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Cheered Out", description = "Well gosh, we've cleaned up quite a bit here!\n\n<Kelsey clears her throat.>\n\nListen, {name}, I'm looking forward to finally vacating this killbox so I can get away from these goblins and drop the cheer-act. If you'd like to continue to advance the interests of Gnomeregan, and by extension the Alliance, in the area, head south to Bootlegger Outpost.\n\nTalk to Zeke Bootscuff there, and remember that any work for the Steamwheedle will help us shut the Bilgewater out of Tanaris for good.", completion = "You know, I'm usually not impressed when I see a {race}, but I've heard about what you've been doin' for the Steamwheedle. You're alright, kid.", objectives = "Talk to Zeke Bootscuff at Bootlegger Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26890] = { id = 26890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Essence of Aku'Mai", description = "Within the beginning tunnels of Blackfathom Deeps, there are large sapphire clusters along the cave walls. We noticed that the naga started harvesting the crystals around the same time their weaponry greatly improved.\n\nThe crystals seem to have great elemental power and, if used inappropriately, could make for a powerful component for my smithing.\n\nWill you help me, {name}? Blackfathom Deeps can be found along Zoram Strand to the north of our outpost.", progress = "How goes your search for the crystals, {name}? Do you think they'll make an item we can use to stop the naga?", completion = "Excellent! These will do nicely. Here's a reward for your hard work.", objectives = "Collect 20 Sapphires of Aku'Mai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26891] = { id = 26891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amongst the Ruins", description = "The Twilight's Hammer has moved into the Moonshrine Ruins here.  Their presence can only serve to coerce the elements into working against us.\n\n{name}, find the Twilight agents here, then find the ruin's fathom stone; it should be somewhere underwater, probably right underneath their own noses. In it is a fathom core - a device that when properly read it will relate a history of all elemental activity.  If I have it, the Earthen Ring and I can hopefully do something to stop them!", progress = "Have you been successful in locating the fathom core?  Without it we'll have no idea what the Twilight's Hammer is exactly up to down there.", completion = "This is exactly what I need!  A fathom core is an incredible well of information that we will be able to draw much good from.  Whatever the Twilight's Hammer is up to in there - and believe me when I say it is no good - my comrades and I will now uncover.\n\nYou've done well here today; the Earthen Ring looks upon you warmly for assisting us.  You've also helped the Horde as a whole, and for that you should be proud.", objectives = "Extract the Fathom Core.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26892] = { id = 26892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep in the Deeps", description = "The Naga and the Twilight's Hammer work together to undo all the progress we've made in this area. What's more, Je'neu tells me that he feels the presence of an Old God lingering far beneath us.\n\nIf they wish to witness chaos, we will give them just that.\n\n{name}, cut down their strongest warriors, and we'll see how much they enjoy it.\n\nSearch carefully, Blackfathom Deeps is full of underwater passages and side paths in the caves that may hide your targets.", completion = "I can hear their cries from here! Maybe this will show them how foolish it is to wish for the return of an Old God.", objectives = "Slay Ghamoo-Ra, Lady Sarevess, and Gelihast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26893] = { id = 26893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackfathom Deeps", description = "There's a task to be done that you're perfect for, {class}. We need to secure the area around Blackfathom Deeps to help with the Alliance that are threatening Zoram'gar Outpost west of here.\n\nGo to Blackfathom Deeps, north of Zoram'gar Outpost, and speak with Je'neu of the Earthen Ring. He will have plenty for you to do.", sourceObjective = "Speak with Je'neu Sancrea.", sourceObjectiveStatus = "unverified-source-field" }
quests[26894] = { id = 26894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackfathom Deeps", description = "The Twilight's Hammer mocks us with their defiance. We will drive them and their allies out of this land for good.\n\nTravel north of here to Blackfathom Deeps and speak with Je'neu Sancrea. He's already made his way inside.\n\nBe wary of Zeya, by the way. She can be a bit...temperamental at times.", completion = "Did Commander Grimfang send you? I've asked him to find suitable recruits to aid me here.", objectives = "Speak with Je'neu Sancrea.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26895] = { id = 26895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thunderdrome!", description = "Hey, friend, you interested in excitement? Adventure? Money? Violence?\n\nWell, you'd better like violence, because they just reopened the Thunderdrome in Gadgetzan. It was sad to see it unused for so long, what with the injury lawsuits, and the racketeering charges, and the copyright infringement... But it's back, and just waiting for burly, savage folk like you to enter and throw down with the foulest opponents ever!\n\nHead to Gadgetzan and talk to Dr. Dealwell to sign up. And tell your friends!", completion = "Another proud {class}, lured by the promise of fame! Of wealth! Of VIOLENCE!\n\nYes, welcome, friend. Welcome... to THUNDERDROME!", objectives = "Talk to Doctor Dealwell in Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26896] = { id = 26896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thunderdrome!", description = "Hey, friend, you interested in excitement? Adventure? Money? Violence?\n\nWell, you'd better like violence, because they just reopened the Thunderdrome in Gadgetzan. It was sad to see it unused for so long, what with the injury lawsuits, and the racketeering charges, and the copyright infringement... But it's back, and just waiting for burly, savage folk like you to enter and throw down with the foulest opponents ever!\n\nHead to Gadgetzan and talk to Dr. Dealwell to sign up. And tell your friends!", completion = "Another proud {class}, lured by the promise of fame! Of wealth! Of VIOLENCE!\n\nYes, welcome, friend. Welcome... to THUNDERDROME!", objectives = "Talk to Doctor Dealwell in Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26897] = { id = 26897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackfathom Deeps", description = "Although our position is exposed, we are safe compared to our friends inside Blackfathom Deeps! They stand mere feet away from the most deadly Twilight's Hammer forces in the area. Speak with Sentinel Aluwyn and give them the aid they desperately need!", completion = "Thank Elune you're here! We could use all the help we can get.", objectives = "Speak with Sentinel Aluwyn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26898] = { id = 26898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackfathom Deeps", description = "I care deeply about these forests, {class}. Things look grim here, but I would rather face the Horde alone than watch them hack and slash their way through the trees.\n\nTravel west to Blackfathom Deeps. Once you're inside, find Sentinel Aluwyn. She's a trusted friend in need of help.\n\nThe orcs in Zoram'gar Outpost threaten her position as we speak. If they take Blackfathom, they will surely cut every tree down to fuel their insanity.", completion = "Thank Elune you're here! We could use all the help we can get.", objectives = "Speak with Sentinel Aluwyn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26899] = { id = 26899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Enemy of My Enemy", description = "Cultists...sacrifice...power...\n\nEnemy...awaken...\n\nOld God...imprison...me...\n\nLord...Kelris...\n\nBring head...revenge...\n\nERADICATE!!!", progress = "Revenge...reward...", completion = "<The Flaming Eradicator appears to concentrate.>\n\nI spare your life for your help, {race}. Leave now...before I change my...mind.", objectives = "Obtain the head of Twilight Lord Kelris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26900] = { id = 26900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agamaggan", description = "I sense a being of immense power within these twisted thorns, {name}. The entire area has come alive at its presence.\n\nIt must be the Spirit of Agamaggan! He was one of the first and most powerful beings to ever live - the Quilboar worship him fervently.\n\nAll the vines you see across the land are a result of his blood; of his sacrifice to save Azeroth in the War of the Ancients.\n\nIf there's any being that could steer the Quilboar towards their noble roots, it would be him.\n\nYou must seek him out.", sourceObjective = "Find the Spirit of Agamaggan.", sourceObjectiveStatus = "unverified-source-field" }
quests[26901] = { id = 26901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going, Going, Guano!", description = "The bats native to Razorfen Kraul produce a very peculiar natural substance. Their guano's stench seems to send the Quilboar into a murderous frenzy - and this place reeks of it!\n\nI need you to find the bat cave, and bring me a suitable sample. If we can reverse the effects and produce an antidote, we may be able to save the Quilboar.", progress = "Ah, I see you have returned. Were you able to procure any Kraul Guano?", completion = "Well done! This is just what we need, {name}.", objectives = "Extract 1 pile of Kraul Guano.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26902] = { id = 26902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Back to Town Accepted Tracking Event" }
quests[26903] = { id = 26903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willix the Importer", description = "At last, help has arrived!\n\nYou have no clue how long I've been held prisoner here. I can't remember the last time I saw the outside of this place.\n\nYou see, I am an entrepreneur. Always out for a copper, as they say. I caught wind that pig snouts were selling outrageously high in the market. I figured it would be an easy in, easy out kind of affair. As you can see, I was a bit wrong!\n\nAnyway, if you'd be so kind as to help me get out of here, I'll make it worth your while.", completion = "Thanks again, friend! I told you I'd make it worth your while.", objectives = "Escort Willix the Importer to the exit of Razorfen Kraul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26904] = { id = 26904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corruption", description = "Few people, especially among our allies, truly understand the nature of the power we wield. They shun us for pursuing knowledge that they are too weak to use properly.\n\nAs you become more powerful, you will begin to discover new spells, further magnifying your power.\n\nGo, get more experience, then return once you've learned a new spell. We'll see if you have it in you to truly master the dark arts.", completion = "As you continue to gain power, return to me and I will teach you new spells and techniques.", objectives = "Reach level 3 to learn Corruption, then cast it 5 times on a Training Dummy near the entrance to Anvilmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26905] = { id = 26905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agamaggan's Charge", description = "Listen closely, mortal.\n\nThe Quilboar are my children. My blood runs deep in these lands.\n\nCharlga Razorflank has steered my children into darkness, driven into insanity by the Scourge.\n\nSlay her, {name}. Slay her and open my childrens' eyes.\n\nGive the Quilboar the chance to return to their noble roots. Let them once more earn my blessing.\n\nBring me her heart!!!", progress = "<The Spirit of Agamaggan stares at you patiently.>", completion = "Take this gift. You have earned my blessing this day.", objectives = "Take Charlga Razorflank's heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26906] = { id = 26906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agamaggan", description = "I sense a being of immense power within these twisted thorns, {name}. The entire area has come alive at its presence.\n\nIt must be the Spirit of Agamaggan! He was one of the first and most powerful beings to ever live - the Quilboar worship him fervently.\n\nAll the vines you see across the land are a result of his blood; of his sacrifice to save Azeroth in the War of the Ancients.\n\nIf there's any being that could steer the Quilboar towards their noble roots, it would be him.\n\nYou must seek him out.", completion = "<The Spirit of Agamaggan looks at you. An ancient voice echoes inside your head.>\n\nI've been waiting for you to come here.", objectives = "Talk to the Spirit of Agamaggan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26907] = { id = 26907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Them Down!", description = "In order to maintain the relative safety in the Southern Barrens, we must put a stop to the current leadership of the Razorfen tribe. Although Charlga Razorflank commands her people through powerful mysticism, her true power is in the strength of the elders around her.\n\nSlay them. Hunt down Bonetusk, the pack leader. Stop Roogug, the overseer of Geomancers. Crush Ramtusk, the quilboar Warlord.\n\nReturn to me when the deed is done.", completion = "You've done well this day. Agathelos would have taken many lives in its fury.", objectives = "Kill Hunter Bonetusk, Roogug, and Warlord Ramtusk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26908] = { id = 26908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeling Thorny", description = "Mankrik's furor over his dead wife raises further concerns, {class}.\n\nThe quilboar in Razorfen Kraul are far more ruthless and full of hatred than Mankrik could ever imagine.\n\nYou should travel south there and speak with my old friend Auld Stonespire. He works to put an end to their rampage before the land suffers more in its already weak condition.", completion = "Only a veteran like you could brave the dangers lurking here.", objectives = "Speak to Auld Stonespire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26909] = { id = 26909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stone Shards", description = "Ancient stones are strewn across this land. The elements flock to them, surrounding them protectively.\n\nThese are sites of great power, and the largest is just west of Hammerfall. Not a soul trespasses, but if you go there alone, you can hear whispers from the earth itself.\n\nI have not visited there in a long while... but our grunts have told me the whispers have started again. Would you look for me? Will you see if the stones still speak?", completion = "<The shards pulse softly, and a whisper slowly echoes through your head.>\n\nHelp...", objectives = "Investigate the Shards of Myzrael.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26910] = { id = 26910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etched Letter", description = "I was asked to bring this to your attention as soon as you returned from dealing with the Blackrock spies, {name}. It appears to be a letter sealed with the insignia of Ashley Blank, our local hunter trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", progress = "Hello, {name}. Is there something I can do for you?", completion = "So you received my note? Excellent. You've proven yourself quite capable in dealing with those orcs. As you continue to grow in power, I will teach you some new techniques.", objectives = "Read the Etched Letter and speak to Ashley Blank in Northshire Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26911] = { id = 26911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Myzrael's Tale", description = "As the stone goes quiet, you're left with a vague sense of unease. Something isn't right.\n\nPerhaps you should tell Zaruk of what you've done so far.", completion = "I know, {name}. I should not have sent you.\n\nForgive me... the whispers of the past are sometimes too strong.", objectives = "Return to Zaruk at Hammerfall in Arathi Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26912] = { id = 26912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Princess Unleashed", description = "Myzrael is a deceiver. She is an ancient force sealed long ago, and must be kept that way.\n\nYou must confront her at the Shards of Myzrael where you first spoke with her.  Summon her with this scroll, and when she has been fully brought to the surface, defeat her. Then take the Eldritch Shackles from her body and place them on the Shards to keep her fully bound once more.\n\nGood luck, {name}... may my past trouble you no more.", progress = "The Shards of Myzrael are now strangely quiet.", completion = "As the eldritch shackles are placed around the Shards, an unhuman wail is heard from far below.  The scream is followed by a roar.\n\nThe Shards of Myzrael no longer invoke feelings of warmth and security as they once did.  Now they pulse with an open menace... as if the thing beneath them holds ill will toward the surface.", objectives = "Summon and defeat Myzrael at the Shards of Myzrael.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26913] = { id = 26913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charging into Battle", description = "Now that you've had the chance to test your abilities in battle, it's time to explain one more reason why training is so important.\n\nAs you get more experience, you'll be able to do new techniques you never thought of.\n\nGo, get some experience, learn a new skill, and demonstrate it on one of the training dummies.", completion = "You're a quick learner, {name}. Return to me as you grow stronger and I'll show you other combat techniques.", objectives = "Reach level 3 to learn Charge, then practice using Charge on a Training Dummy south of the entrance to Northshire Abbey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26914] = { id = 26914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corruption", description = "We must take care in how we speak around the abbey and its environs, but don't let that deter you from the path of power.\n\nAs you become more powerful, you will begin to hear the fel voices, granting you their power in the dark arts.\n\nGo, get more experience and learn a new spell. Once you have, practice it on the training dummies.", completion = "I see you have already mastered Immolation! I look forward to instructing you in the future. Do not forget to return for further lessons as you grow in power.", objectives = "Reach level 3 to learn the Corruption ability, then practice casting Corruption 5 times on a Training Dummy south of the entrance to Northshire Abbey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26915] = { id = 26915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deepest Cut", description = "By now, you know the basics of combat as rogue, but I want to teach you a new skill. As rogues, we are renowned for our ability to execute chains of combat techniques, often saving the most powerful strikes for the end.\n\nAs you get more experience, you'll learn new things - and this is one of the ones you'll learn first. Once you have, I want you to go try it on one of the training dummies south of the entrance to the abbey.", completion = "You've caught on quickly, {name}, and a quick mind will serve you well. Return to me as you grow in power and I will show you new techniques.", objectives = "Reach level 3 to learn Eviscerate, then find a Training Dummy south of the entrance to Northshire Abbey and practice Eviscerate 3 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26916] = { id = 26916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastering the Arcane", description = "As a mage, you will learn a variety of spells as your understanding grows. All you need to do is get some more experience, and the secrets of the arcane will reveal themselves to you.\n\nYou'll see. Go develop your powers, and show me what you learn.", completion = "Have you mastered the use of Arcane Missiles already? You are a quick study in the arcane arts and you have a promising future ahead. Don't forget to return to me for training as you grow in power.", objectives = "Reach level 3 to learn Frost Nova, then practice casting it 2 times on a Training Dummy south of the entrance to Northshire Abbey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26917] = { id = 26917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter's Path", description = "I've heard about your help in clearing out some of the orcs. You've shown that you can handle yourself in combat.\n\nAs you get more experience in combat, you'll start learning how to do new things. I want you to go, get some more experience, then try the new abilities you learn on one of the training dummies south of the entrance to the abbey.", completion = "I knew you would master Steady Shot quickly. I'm looking forward to showing you other techniques as you get more experienced in the ways of the {class}.", objectives = "Reach level 3 to learn Steady Shot, then find a Training Dummy south of the entrance to Northshire Abbey and practice using Steady Shot 5 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26918] = { id = 26918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of the Light", description = "As you continue in your journey as a Paladin, you'll become closer to the light, learning new abilities.\n\nGo, get more experience, and learn a new ability. Demonstrate it for me, and we will continue your training.", completion = "You're a quick learner, {name}. Return to me as you grow stronger and I'll teach you more about using the Light to vanquish your enemies and strengthen your allies.", objectives = "Reach level 3 to learn Seal of Command. Cast Seal of Command on yourself and then hit a Training Dummy south of the entrance to Northshire Abbey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26919] = { id = 26919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning the Word", description = "One of your responsibilities as a priest is caring for the wounded. Another is to go out into the world and be more... proactive about defending them.\n\nAs you do so, you'll grow in power and learn all sorts of new things.\n\nWhy don't you go out, get more experience, and then return to demonstrate what you've learned?", completion = "You're a quick learner, {name}, and the wounded are fortunate to have your aid. Return to me as you grow stronger and I'll teach you other spells.", objectives = "Reach level 3 to learn Shadow Word: Pain, then use it 5 times on training dummies near Northshire Abbey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26920] = { id = 26920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Andorhal", description = "Hurry, {name}... there isn't time to waste.\n\nThe city of Andorhal is in the middle of a three-way war between the Forsaken, the Alliance, and the Scourge.  Lady Sylvanas has sent one of her best death knights to lead the charge for her cause, but I'm sure he can use all the help he can get.  With Arthas dead, now is the perfect time for the Forsaken to take Andorhal.\n\nSpeak with the bat handler, Timothy Cunningham, when you are ready, and he will put you on the first flight out there.", completion = "It's about time you arrived, {class}.", objectives = "Report to Koltira Deathweaver within Andorhal in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26921] = { id = 26921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scourge First... Alliance Later", description = "Darkmaster Gandling of the Cult of the Damned leads the Scourge offensive here in Andorhal.  My old counterpart, Thassarian, leads the Alliance forces.  If we're to win Andorhal, we'll have to defeat both, but we will certainly fail if we take on both at once.\n\nI know Thassarian well enough to know that he will focus on the Scourge first.  We will do the same.\n\nTake out the weaker, desiccated Scourge to reduce their numbers.  The Alliance will have to wait to taste our wrath.", completion = "You may not act quickly, but at least you do not fail me.\n\nVery well.  I will have a more important task for you, {name}, when the time is right.", objectives = "Slay 15 Desiccated Scourge within Andorhal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26922] = { id = 26922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Endless Flow", description = "Araj the Summoner is bolstering the Scourge defenses with simple skeletons... an army of weaklings that will overwhelm you before it overpowers you.  He has assembled animi within Andorhal's northern towers that spew these skeletons out at an alarming rate.  But I've got the solution!\n\n<Jearl passes you a handful of grenades.>\n\nTheir function is simple.  Throwing these grenades at a bone animus... or, for that matter, a mob of skeletons... will reduce them to splinters.", progress = "I know what those devices sound like when they've blown up... and I haven't heard that sound yet.  Get back out there, {name}.", completion = "These grenades are all explosives, nothing more.  Even as a member of the Royal Apothecary Society, I recognize that some problems are not solved by throwing more plague at them.", objectives = "Use Jearl's Hand Grenades to kill 5 Stickbone Berserkers and to destroy a Scourge Bone Animus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26923] = { id = 26923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War Machines", description = "You fools will never defeat the Scourge with those abominations running around.  Koltira blathers on about reducing their numbers, but the Scourge's best weapon here in Andorhal can be found in those lumbering brutes that are throwing my deathguards around like ragdolls.\n\nI won't have it.  {name}, enter the battlefield and destroy those monsters.", completion = "With the behemoths out of the way, our victory against the Scourge is inevitable.\n\nOur current chances against the Alliance aren't quite as favorable... but that's no concern of yours.  Not yet, anyhow.", objectives = "Destroy 6 Opengut Behemoths in Andorhal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26924] = { id = 26924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scholomancer", description = "The Scholomance is one of the few Scourge holdouts remaining west of the Thondroril.  The headmaster of Scholomance, a cultist by the name of Darkmaster Gandling, has made an appearance on the battlefield.\n\nThis will be his final mistake.\n\nYou will find Gandling in a square near the southern end of town.  I want you to fight and weaken Gandling.  I will join you to help finish him off.", completion = "Excellently done, {name}.  And now, with the leader of the Scourge forces eliminated from Andorhal, we bide our time.", objectives = "Kill Darkmaster Gandling within Andorhal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26925] = { id = 26925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Araj the Summoner", description = "With the animus destroyed, the next logical step is to take out Araj himself, and to take a shard of his phylactery.  You've probably already seen him, lurking at the fountain in the center of town.\n\nTake my grenades with you.  They won't do anything to Araj, but if he decides to summon any of those skeletons, you can use them to blow them away.  Again.", progress = "Araj is a formidable opponent.  Be prepared.", completion = "Araj dead... this is good.  The Royal Apothecary Society has done its part.  As have you, {name}.", objectives = "Kill Araj the Summoner. You may use Jearl's Hand Grenades to destroy Stickbone Berserkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26926] = { id = 26926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory, For Now", description = "The Forsaken are victorious, and our forces are still strong.  Military strategy dictates that we attack the Alliance now, while they are recovering and unaware.  I have other plans, however...\n\nWe will wait.  We attack Thassarian and his troops when the time is right.  In the meantime, speak with Rhonda Molver and take a flight to the Bulwark, on the Plaguelands' western border.  High Executor Derrington will give you your next assignment.\n\nYou will hear from me when you are needed again in Andorhal.", completion = "Word arrived shortly before you did, {name}.  With the Scourge ejected from Andorhal, the Forsaken has cemented its foothold in Lordaeron.", objectives = "Report to High Executor Derrington at the Bulwark in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26927] = { id = 26927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suddenly, Murlocs!", description = "So we've got troggs working for kobolds, and kobolds working for gnolls. The gnolls must've moved in from the Wetlands.\n\nHow do I know? Well, they brought friends, because what's left of the Loch is swarming with Bluegill murlocs that were never there before.\n\nPests are pests, but this coordination is worrying. I need you to talk to Cannary Caskshot. She's one of the best hunters in these parts, and she'll know how to handle murlocs, if you can pull her away from her mug long enough.", completion = "Murlocs? Sure, I've hunted murlocs.\n\nAnd every single stinkin' one of them deserved what they got! You hear me?", objectives = "Speak with Cannary Caskshot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26928] = { id = 26928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smells Like A Plan", description = "Murlocs workin' with gnolls? That's a laugh! Now, just killin' them won't get you anywhere. Too many of the buggers.\n\nBut I've got a plan, usin' the old noggin, see. Those murlocs, they have this smell, they get that smell on stuff, and when another murloc smells it, they go all crazy! Makes great bait for 'em.\n\nAnyway, they've got little glands that have that smell in 'em. You go and get me a bunch of those.", progress = "Now don't you stink all to high hell! I'm assumin' that's because of the murlocs, but it's hard to tell.", completion = "Phew! Ain't that a stench.\n\nNow you prepare yourself, because I'm about to wow you with what's left of my mental faculties.", objectives = "Collect 7 Murloc Scent Glands from any Bluegill Murloc in The Loch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26929] = { id = 26929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Load of Croc", description = "Now while you're runnin' around doin' whatever the heck it is that you do, would you mind helpin' me out a bit?\n\nSee, I usually go out huntin' crocolisks down in the loch, but given certain circumstances, I'd rather sit here right now. Mighty polite of you not to give me grief over it, thanks!\n\nSo seein' as how you're such a <gentleman/lady>, why don't you bring me back some crocolisk jaws and I'll give you some mostly-clean money in return.", progress = "So did you get those crocolisk things or did I make that up?", completion = "Mighty kind of you to help out an ol' fool like me. Here's your reward as promised an' all.", objectives = "Collect 6 Crocolisk Jaws.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26930] = { id = 26930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "After the Crusade", description = "Our victories are quickly piling up, {name}.  The Scarlet Crusade, which has long persecuted the Forsaken, is on its last legs.  While they still hold their monastery here in Tirisfal, they no longer occupy Hearthglen, or Tyr's Hand, far to the east.\n\nAs recently as last week, there have been reports of Scarlet Crusade activity at a small camp east of Felstone Field, but I have reason to believe that they too have been eliminated.  Travel there, and verify this information for me.", completion = "Burning bodies?  No survivors?  I guessed correctly.\n\nAll the better!  We're better off without the Scarlet taint upon Lordaeron.  They epitomized all the worst things about humans.", objectives = "Scout the Scarlet Crusade camp located east of Felstone Field in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26931] = { id = 26931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foxes and Hounds", description = "These Alliance forces walk around the Plaguelands like they own the place.  Well, they don't!  This land rightfully belongs to the Dark Lady!\n\nAs the battle for Andorhal drew to a close, the Alliance forces occupying the Plaguelands scattered.  Several of them can be found just east of here, hunting foxes.  Prove to them that this is Forsaken territory.\n\nKill the hunters.  Kill their hunting dogs.  And kill the foxes they hunt, for good measure.", completion = "It's a relief to have those hunters out of the way.  We're not done killing Alliance, however...", objectives = "Kill 4 Alliance Fox Hunters, 4 Bullmastiffs, and 4 Whitetail Foxes in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26932] = { id = 26932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buzz Off", description = "When the Stonewrought Dam burst, it drained near the entire loch. Horrible ecological devastation.\n\nAnd don't you go thinking it didn't really affect us dwarves! Not only are we plumb out of fish, but there's acres of dead threshadons out there left to rot in the sun. The buzzards are after them, and they're spreading all manner of filth and disease right on the outskirts of town.\n\nI can't ask you to clean it all up, but could you deal with the buzzards? Killin' even just a few will help.", progress = "Plenty of 'em flappin' around yet, lad.", completion = "That should help prevent disease and illness from spreading into our remaining water. Many thanks, {name}.", objectives = "Kill 8 Loch Buzzards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26933] = { id = 26933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foes Before Hoes", description = "The men who till Felstone Field are no farmers.  They're soldiers.\n\nThassarian's forces needed food, so he sent some of the Alliance north from Andorhal, to tend Felstone Field.  The battle for Andorhal may be over, but another battle looms... Forsaken versus human.  Killing those soldiers that work at Felstone will give the Dark Lady's forces a decided advantage.", completion = "Ha ha!  I hope that they come back as zombies.", objectives = "Kill 9 Alliance Laborers on Felstone Field.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26934] = { id = 26934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Latent Disease", description = "I need plagued grass for an... an experiment, of sorts.  Those Argent Crusaders and those infernal Cenarion druids have done too good a job of healing the plaguelands, however... and I can't find proper reagents within a reasonable walking distance.\n\nSome of the local wildlife retain the plague's touch, however.  Kill a diseased black bear, then retrieve the grass that grows where its decaying body lies.  It's not optimal, but it'll do.", progress = "Animal tissue holds onto disease so much better than plant tissue, doesn't it?", completion = "Glorious!  This is the last bit I need.\n\nActually, stick around, {name}.  Let me tell you a little bit more about our plan.", objectives = "Kill Diseased Black Bears in Western Plaguelands, then loot 20 Plague Tangles that grow near their corpses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26935] = { id = 26935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northridge Lumber Mill", description = "We are not the only Argent Crusaders here in the plaguelands.  Our headquarters, Hearthglen, lies to the north.  Even nearer to the north is a small lumber mill which we also control.\n\nNathaniel Dumah is my main contact at the lumber mill.  I encourage you to speak with him, should you find yourself in that part of the woods.", completion = "Welcome to Northridge, {class}.", objectives = "Report to Nathaniel Dumah at the Northridge Lumber Mill in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26936] = { id = 26936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lower the Boom", objectives = "Felstone is cleared and the bombs are set.  I hope you're ready.  I recommend covering your ears.\n\n<Derrington looks down and places his finger on an ignition switch.>\n\nEVERYBODY, PREPARE FOR IGNITION!  IN 3...\n\n2....\n\n1...", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26937] = { id = 26937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Death is Not Enough", description = "Derrington and his men don't know it, but it was I who ordered the plaguing of Felstone Field.  We need this area for practice.  If we're to win this war for Andorhal, we need to use our newest, most versatile weapon:\n\nVal'kyr.\n\nTake my enthralled val'kyr with you, {name}, and kill the simpering Alliance scum that remain on Felstone.  Once they are dead, she will bring them back to this world... as one of us.\n\nThe Forsaken shall not die out!", completion = "I am able to communicate with you through the Val'kyr, {name}.  You have done well.\n\nRemain on Felstone Field.  We must now teach these newly-converted Forsaken how to fight.", objectives = "Kill 8 Alliance Laborers on Felstone Field so your Enthralled Val'kyr can convert them into Forsaken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26938] = { id = 26938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combat Training", description = "A val'kyr's only purpose is to serve, and this one serves you.  I am now giving you full control over her abilities, {name}.\n\nRoaming around the farm's outskirts, you should find several of the Forsaken that you just created.  I want you to use your val'kyr to gather at least five of them.  Once you have done so, take your newly-formed band of soldiers, bring them into Felstone's barn, and kill the beast inside.  Today, they will learn what it means to fight for the Dark Lady.", progress = "You try my patience, young {name}.", completion = "When Koltira gives his word, I will bring these val'kyr into Andorhal.  We will win.  And yet another piece of Lordaeron will fall to the might of the Forsaken.", objectives = "Use your Enthralled Val'kyr's Call to Arms ability to mobilize 5 Forsaken Troopers on Felstone Field. Then slay the Opengut Abomination inside Felstone's barn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26939] = { id = 26939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The G-Team", description = "How did you get in here?\n\nOh, it doesn't matter. I'm Murd Doc of the G-Team. We're the best there is, and we're here to retake Gnomeregan!\n\nWhen nobody else could help him, the High Tinker found and hired us.\n\nBut we simply can't do this alone! You're an honorary G-Team Commando now, {name}.\n\nTake this parachute, jump down straight ahead into the Hall of Gears, and kill the Viscous Fallout. After you're done, report to Commando B.E Barechus by the west hallway. You two will get along great, I'm sure.", progress = "What're you doing out in the open like that, fool? Get down!", completion = "I hope that wasn't too much for you. The mission is far from over!", objectives = "Kill the Viscous Fallout.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26940] = { id = 26940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost Nova", description = "We are the heirs to a legacy of arcane magic and your path will not be an easy one. Many still hold us responsible for the actions of our forebears, but our talents are needed.\n\nThough you must be cautious, it is important to develop your powers, as that will deepen your connection to the arcane and grant you access to new spells.\n\nGo - get more experience with your spells, and demonstrate what you learn for me.", completion = "I knew you would master this lesson quickly. You are a credit to the highborn and to all our kin. Remember, as you grow in power, return to me and will instruct you further.", objectives = "Reach level 3 to learn Frost Nova. Look for a Training Dummy near, and practice using it twice.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26941] = { id = 26941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The G-Team", description = "That Murd Doc is crazy, {class}. Never, ever, let you find yourself in an aircraft with that gnome.\n\nStealth usually isn't my thing, and it's certainly not going to be yours. Go down this hallway to the Launch Bay and dispose of the Electrocutioner 6000.\n\nThe Electrocutioner is in charge of the aircraft...\n\n...and I hate aircraft. I'm not getting in any sort of aircraft!\n\nUse this parachute to drop down afterwards and speak with Commando Face for your next job.", progress = "Woah! How did you see me!?", completion = "Took you long enough. Get behind the pillar with me before you blow our cover!", objectives = "Kill the Electrocutioner 6000.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26942] = { id = 26942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The G-Team", description = "I'd keep my distance from B.E Barechus and Murd Doc, neither is terribly stable.\n\nYou are, though, so let's get you to work! Go down into this tunnel until you get to Tinkers' Court. Hopefully you'll know what to do when you meet Mekgineer Thermaplugg.\n\nOur leader, Commando Hann Ibal waits somewhere in there. He'll reward you handsomely for all your work.\n\nProbably.", completion = "I'd love for you to come aboard as a full G-Team Commando, but you have other adventures to pursue.\n\nI'm sure we'll meet again, and I hope you'll have considered joining by then. Here's something for your trouble.", objectives = "Kill Mekgineer Thermaplugg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26943] = { id = 26943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home Sweet Gnome", description = "I used t' have quite the home back in Ironforge. That is, I did until I was booted out to make way for the gnomes.\n\nThey couldn't stop a bunch of troggs with all them gizmos and machines! An' I have to pay for their weakness?\n\nNo, sir. No longer.\n\nGo to Gnomeregan and talk to Commando Murd Doc. Sure, he's a gnome, but his crew, S.A.F.E. I think they call 'em, are going to take Gnomeregan back.\n\nGo! I want my house back!", completion = "Never thought I'd see a {race} like you down here. Any particular reason you're risking life and limb?", objectives = "Speak to Murd Doc.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26944] = { id = 26944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exploring Gnomeregan", description = "The gnomish capital, Gnomeregan, hasn't been under their control for some time now. I know what it feels like to lose a home.\n\nPlease, venture inside Gnomeregan and speak to Commando Murd Doc, a member of S.A.F.E. If there's anything at all that you can do to help them take their home, I urge you to do so. There are dark secrets in those halls.", completion = "Never thought I'd see a {race} like you down here. Any particular reason you're risking life and limb?", objectives = "Speak to Murd Doc.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26945] = { id = 26945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning New Techniques", description = "As you overcome the challenges before you, you'll begin to learn new techniques.\n\nGo, get more experience, and learn a new skill. Then demonstrate it for me on one of the training dummies.", completion = "You've proven a capable student. When it is time to resume your training, return to me and I will show you other techniques.", objectives = "Reach level 3 to learn Charge. Look for a Training Dummy and practice using Charge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26946] = { id = 26946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rogue's Advantage", description = "I'm certain that by now, you've mastered using Sinister Strike against your enemies. But, as you learn more and advance as a rogue, you'll start to figure out new techniques. One you should figure out soon is called Eviscerate. It can be a strong way to end a combination of attacks.\n\nI want you to get some more experience, figure it out, then try it on a training dummy near the southeastern edge of Aldrassil.", completion = "You've learned quickly. If you are as sharp as you seem to be, you may prove to be one of my best students yet. Return to me when you are in need of further training.", objectives = "Reach Level 3 and Learn Eviscerate. Look for a Training Dummy southeast of Aldrassil and practice using Eviscerate 3 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26947] = { id = 26947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Woodsman's Training", description = "When most people think of the kaldorei, they conjure visions of druids and sentinels, but the way of the hunter is just as ancient and just as venerable.\n\nI've been observing you, and you've had quite a bit of experience handling that bow. As you gain more, you'll start to learn some new abilities.\n\nI want you to go out, get some more experience, and figure out how to do something new. Then go use it on a training dummy near the southeastern edge of Aldrassil.", completion = "You are a quick study in our ways. I look forward to continuing your training in the future. Return to me when the time is right.", objectives = "Reach level 3 to learn Steady Shot. Look for a Training Dummy southeast of Aldrassil, and practice using Steady Shot 5 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26948] = { id = 26948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moonfire", description = "Druids play an important role in our society, but all too often we are seen as passive dreamers in a world that is changing around us.\n\nThe truth is, though, we must actively practice and go out onto the world to develop our connection to nature.\n\nSo go, get some more experience. You will begin to feel your connection deepen, learning new skills. Demonstrate the first you learn for me.", completion = "You have mastered the basics of the healing ways quickly, {name}. I have no doubt that your healing skills will often come in handy. Return to me when you need further training.", objectives = "Reach level 3 to learn Moonfire. Use it on a training dummy in Aldrassil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26949] = { id = 26949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning the Word", description = "As you venture out into the world and develop your skills, you will begin to learn new abilities that you never knew you had within you.\n\nI'd like you to go out, get some more experience, and then show me the first new ability you learn.", completion = "You will find no lack of allies in need of healing. Return to me when you need further training.", objectives = "Reach level 3 to learn Shadow Word: Pain, then use it 5 times on training dummies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26950] = { id = 26950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Side of the Light", description = "The Scarlet Crusade lures in anxious young warriors with their promise to eradicate the undead. What they don't see is the dark underbelly of the entire operation.\n\nInterrogator Vishas is the cruelest man I've ever had the displeasure to meet - he 'extracted' information from my mother during the initial outbreak of the plague. The merciless Bloodmage Thalnos watches over their graveyard.\n\nThe crusaders' zealous holy rage blinds them from their own darkness. Make them regret their hypocrisy.", completion = "What do you mean Thalnos was an undead? That's impossible. This is a holy place, the Scarlet Crusade would never allow...\n\nTake this as a reward, and get some rest. The crypts must have gotten the best of your nerves.", objectives = "Kill Interrogator Vishas and Bloodmage Thalnos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26951] = { id = 26951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleanup on Isle E.", description = "The Battle to reclaim the Echo Isles was a costly one.  But well worth it, {class}.  The great spirit, Bwonsamdi, helped our warriors defeat the foul Zalazane.  He protected our warriors with spirits from the island.  But some of those spirits fell in battle.  Help put those spirits to rest.  On the Echo Isles, you will find masks laying about gather them and bring them here.", progress = "Have you gathered the masks, {class}?", completion = "Thanks, {class}.  The spirits can rest now.  As long as we show them respect they will bless us and our new home for a long time.  Spirits be with you, {name}.", objectives = "Gather 8 Disenchanted Tiki Masks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26952] = { id = 26952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Menders' Stead", description = "I don't like the looks of what the Forsaken are doing here at the Bulwark.  Bombs, cauldrons, needless bloodshed... none of these embody that which the Argent Crusade stands for.  Furthermore, I don't like the fact that they employ mercenaries like yourself.\n\nNothing against you personally, {class}.  It's just that you could be doing so much more for yourself.  If you're interested in healing the plaguelands, rather than re-plaguing them, then report to Field Agent Kaartish at the Menders' Stead to the east.", completion = "Welcome, {class}.  As you can see, our camp is a joint expedition between Argent Crusade members and Cenarion Circle druids, but we welcome all who wish to help heal the land.", objectives = "Report to Field Agent Kaartish at the Menders' Stead in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26953] = { id = 26953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zen'Kiki, the Druid", description = "I am Adrine Towhide, a druid of the Cenarion Circle.  You can thank us for healing this land, where once there was only death.\n\nWe accept all who choose to follow the druidic path, regardless of race, faction, or talent.  Occasionally that means we enlist a druid who needs more help than others.\n\nI'd like you to meet Zen'Kiki.  He's pretty new, and he's still learning his craft.  Would you mind taking him out with you for a while?  You can practice combat on the plagued animals that roam nearby.", completion = "It looks like Zen'Kiki is still having a little bit of trouble with his shapeshifting.", objectives = "Kill 20 plagued wildlife with Zen'Kiki by your side. You may kill Hulking Plaguebears, Diseased Wolves, Venom Mist Lurkers, or Plague Lurkers.\n\nReturn to the Menders' Stead if you become separated from Zen'Kiki.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26954] = { id = 26954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Different Approach", description = "Among other things, Zen'Kiki needs to work on his spell accuracy.  I could see his wrath spells spiraling out of control even from here!  In fact, I used them as a marker to follow your progress through the woods.\n\nPerhaps we can use Zen'Kiki another way.  Take him up to the top of the hill just to our east.  The diseased hawks that circle above that hill must be destroyed.  Ask Zen'Kiki to shoot at these hawks.  Even if he can't hit them, he will distract them so you can finish them off.", progress = "Back so soon?", completion = "Now we're getting somewhere.  How many birds did Zen'Kiki end up killing?\n\nNone?  You killed them all yourself?\n\nAlright, I suppose we'll have to find another use for him then.  I will let you know when the time is right.", objectives = "Bring Zen'Kiki to the top of the hill east of the Menders' Stead, then use him to summon and kill 7 Diseased Hawks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26955] = { id = 26955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zen'Kiki and the Cultists", description = "While you've been away, I've been trying a different approach on our friend Zen'Kiki.  I believe he may have a future as a healer.  This is mainly because healing spells never miss.\n\nI hear from Field Agent Kaartish that the cultist camp to the east is where the plagued animals are coming from.  I hope you don't mind escorting Zen'Kiki over there... perhaps he can help heal some of the plagued animals within the camp.", completion = "By the grace of the Earthmother, he's done it!  Thank you, {name}!\n\nI admit, I had nearly given up hope on Zen'Kiki.  It is only due to your patience and diligence that he has come into his own as a druid and member of the Cenarion Circle.  And that's without even mentioning the good you've done for nature.\n\nYou have my admiration and respect.", objectives = "Bring Zen'Kiki to the Malicia Outpost in Western Plaguelands, then break 4 Captive Plaguebears out of their cages and allow Zen'Kiki to heal them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26956] = { id = 26956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Ain't Sayin' You a Gourd-Digger...", description = "{race}!  I'm glad someone's here to help me out.\n\nWe Cenarion druids have re-cultivated Dalson's Farm, immediately behind me.  The land has flourished and our crops have been successful... mostly.\n\nA few plants seem to still be infected by the plague that ran through this land.  Perhaps their roots were too deep, perhaps the seeds were weak... I cannot say.  All I can say is that I need an able {class} like you to help me remove the bad plants from the good ones.", progress = "Have you finished killing... er, removing those plants yet?", completion = "Thank you for your help, {name}.  I know that picking vegetables isn't the most heroic task imaginable, but even the humblest tasks have their rewards.", objectives = "Remove 6 Bad Corn, 4 Rotten Apples, and 3 Unhealthy-Looking Pumpkins from Dalson's Farm in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26957] = { id = 26957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Long Trip Home", description = "I've been many places in my life, good {class}.  I fought the battle for Ahn'Qiraj, passed through the Dark Portal into Outland, and joined the Argent Crusade to beat down Scourge in coldest Northrend.\n\nBut before it all, I was a farmer here in Lordaeron.  Now I find myself here in Hearthglen, a scant few miles from home.  It's time I paid my respects.\n\nI'm headed to the Menders' Stead before I return home.  I wouldn't mind meeting up with you again once I get there.", completion = "It would appear that I arrived before you, {name}.\n\nField Agent Kaartish gave me the details about my old home.  It seems my battles with the Scourge aren't quite over yet.", objectives = "Reconvene with Del Gahrron at the Menders' Stead in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26958] = { id = 26958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your First Lesson", description = "Let's start your training right away. As you get more experience in combat, you'll start to develop new techniques.\n\nGo, get some more experience, learn something new, and demonstrate it on the dummies to the northwest.", completion = "Keep that technique handy, {name}. I find myself using it all the time. Return when you're ready for further training.", objectives = "Reach level 3 to learn Charge. Find a Training Dummy on the northwest side of the Crash Site and practice using Charge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26959] = { id = 26959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stripping Their Defenses", description = "We need to eliminate the Scarlet Monastery's defenses before a true invasion can begin. Venture deep into here, their library, and assassinate Houndmaster Loksey and Arcanist Doan. They maintain the powerful defenses that protect their comrades.\n\nMy own magic will ensure your actions go undetected by the rest of the monastery. Once they are dead, I can summon in additional reinforcements to aid in our attack.\n\nWe must be successful, {name}, the Dark Lady will not tolerate failure in the slightest.", completion = "I knew I could count on you! These fools will never know what hit them.", objectives = "Eliminate Houndmaster Loksey and Arcanist Doan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26960] = { id = 26960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Son, the Prince", description = "Great burdens have been placed on my son's shoulders in his short lifetime, and I fear his responsibilities are only going to grow.\n\nHe will never learn leadership confined to the keep, but I am loath to send him forth without escort.\n\n{name}, your deeds in the wake of this cataclysm are already legendary. You would be an excellent mentor for young Prince Anduin.\n\nPlease, introduce yourself to him. There is some pressing city business that you both can attend to for me.", completion = "Excellent, Anduin will learn a lot by shadowing you.\n\nRemember, stay within the city's borders. Keep him out of trouble. And above all else, guard him with your life.\n\n<King Wrynn turns his attention to his son.>\n\nAnduin, no adventures! Stay close to {name} and return to the keep should you see any trouble.", objectives = "Introduce yourself to Prince Anduin in Stormwind Keep. Speak with King Wrynn once you are both acquainted.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26961] = { id = 26961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Idols", description = "Recently, just before the troggs surfaced within the site, we had uncovered a large number of strange, carved idols. But we didn't have the chance to study them, for soon after their discovery the troggs chased us away from the ruins! And those idols have a strange effect on the troggs. It makes them go berserk!\n\nBring me 8 idols - I want to study them, and I want them out of trogg hands!  You can find the idols on the troggs infesting the site.", progress = "Do you have those idols?  We must study them and report our findings to Ironforge!", completion = "You got them!  Nicely done, {name}!\n\nAnd you don't look too worse for wear, even with those berserk troggs about.  I'm going to keep my eye on you...you show some promise.", objectives = "Bring 8 Carved Stone Idols to Magmar Fellhew at Ironband's Excavation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26962] = { id = 26962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stripping Their Offense", description = "As you can see, {name}, our first assault on the Armory did not go as planned. We had taken the nearby courtyard until the Scarlet Champion, Herod, showed up.\n\nWe must continue our assault. The Scarlet Crusade will never be allowed to train another warrior here, let alone launch an attack on the Undercity.\n\nYour task should be obvious. Down the Scarlet Champion.", completion = "Herod is slain! The Armory will fall!", objectives = "Kill Herod.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26963] = { id = 26963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steadying Your Shot", description = "Let's start your training right away. It's going to be a struggle to survive here, and you'll play an important role in making sure our people are safe and well-supplied.\n\nAs you become more experiened, you'll begin to discover new abilities. Go ahead and go out, learn something new, and try it out. Return to me when you think you've mastered it.", completion = "Keep that technique handy, {name}. I find myself using it all the time. Return when you're ready for further training.", objectives = "Reach level 3 to learn Steady Shot. Find a Training Dummy on the northwest side of the Crash Site and practice using Steady Shot 5 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26964] = { id = 26964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Silverpine Forest!", description = "All able-bodied members of the Horde are hereby ordered to report to Grand Executor Mortuus at Forsaken High Command in Silverpine Forest.\n\nNow, more than ever, your help is needed in routing the enemy infestation of the region and conquering the port of Gilneas!\n\nTo reach Forsaken High Command you must travel south through Tirisfal Glades and enter Silverpine Forest. From there, follow the road south until you reach Forsaken High Command.\n\nOnward, <brother/sister>! Destiny calls!", completion = "Most excellent! A new recruit has arrived. There is much to do... much to do I say.", objectives = "Report to Grand Executor Mortuus at Forsaken High Command in Silverpine Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26965] = { id = 26965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warchief Cometh", description = "You're just in time, {name}nub. It is {name}nub, right?\n\n<Grand Executor Mortuus looks at a sheet of paper.>\n\nYes, that's what the paperwork says: \"{name}nub.\"\n\n<Grand Executor Mortuus points to your name on the sheet of paper.>\n\nWhere was I? Oh yes, you're just in time! The Warchief should be arriving at any moment to meet with our leader and savior, the Dark Lady herself. Just stand by and be at your best behavior. I expect that when this demonstration is over we will all receive commendations!", progress = "Stand at attention, Zulazanjinub!", completion = "Well that was unexpected. I am not one to doubt our Warchief, but...\n\nNevermind! We have work to do. I'm sure the Dark Lady and the Warchief will get this all worked out.", objectives = "Stand by for Warchief Garrosh Hellscream's arrival.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26966] = { id = 26966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Light's Power", description = "As a paladin, you're no stranger to the Light that touches all of us. But you also have the unique power to call upon the Light to help you in battle.\n\nAs you gain more experience, you'll grow even closer to the Light and be able to call upon new powers in battle.\n\nGo, grow in experience until you have learned a new power, and then demonstrate it for me.", completion = "You've proven yourself a quick learner, {name}. I look forward to training you again when the time is right.", objectives = "Reach level 3 to learn Seal of Command. Apply Seal of Command, find a Training Dummy on the northwest side of the Crash Site and hit it with an attack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26967] = { id = 26967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for the Scarlet Monastery", description = "Behold the might of the Forsaken! The unstoppable will of the Dark Lady flows through our bodies! \n\nThe vast majority of the crusade's remaining forces have fled. Some, however, remain defiant.\n\nYou have been instrumental in this campaign's success. Sylvanas extends the honor of slaying her last remaining enemies to you, {name}.\n\nShow no mercy.", completion = "Yes! The Scarlet Monastery now belongs to the Forsaken! None can escape our wrath!\n\nYou've completed your task with the precision of a true champion. Take this as a reward, courtesy of the Banshee Queen.", objectives = "Kill Scarlet Commander Mograine and High Inquisitor Whitemane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26968] = { id = 26968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost Nova", description = "In your future as a mage, you'll want to master a wide variety of spells. To do so, you need to deepen your connection by the arcane by growing in power.\n\nGo, get more experience as a mage, and demonstrate what you learn for me.", completion = "You've mastered the use of this new spell quickly, {name}. I only wish all of my students were as talented. Return to me when you find yourself in need of further training.", objectives = "Reach level 3 to learn Frost Nova. Find a Training Dummy on the northwest side of the Crash Site and practice using it 2 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26969] = { id = 26969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Strike", description = "Your walk with the elemental powers will take you to many places. As you grow in power, you will begin to learn new abilities. \n\nLet us start your journey with a simple, but useful, lesson.\n\nLearn the secret of Primal Strike, and then practice your new skill using the training dummies to the northwest of the Crash Site. Return to me when you are finished.", completion = "It is a pleasure to teach such a capable student. As long as you continue the traditons faithfully, the shamanic arts will never be lost to our people again. Return to me when you need further training.", objectives = "Learn Primal Strike by reaching Level 3, and then find a Training Dummy on the northwest side of the Crash Site and practice using Primal Strike 3 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[26970] = { id = 26970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning the Word", description = "As a priest, one of your most important duties is to use the Light's power to aid the wounded.\n\nAnother is to use your power offensively, to protect them.\n\nAs you grow more experienced, you will begin to uncover new abilities that you can use in your charge. Go, gain more experience, and then demonstrate the abilities you have learned to me.", completion = "You'll often find your skills as a healer in demand, {name}. Do not hesitate to return when you need more training.", objectives = "Reach level 3 to learn Shadow Word: Pain, then use it 5 times on target dummies near the crash site.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
